ONLINE_UI={
 'cs':{'intro':'Chcete propojit svůj vůz s aplikací výrobce? Vyberte značku. Najdete zde informace k založení účtu, přihlášení a propojení s vozidlem. Přesný postup závisí na modelu, výbavě a systému infotainmentu.','need':'Pro propojení budete potřebovat účet {account} a aplikaci {app}.','start':'Začněte zde','accountButton':'Přihlásit se nebo vytvořit účet {account}','helpButton':'Otevřít návod k propojení vozidla','combinedButton':'Návod k propojení a aplikace {app}','appButton':'Informace a stažení aplikace {app}','steps':[('1. Přihlaste se nebo si vytvořte účet','Pokud už účet máte, přihlaste se. Jinak si jej založte a potvrďte e-mailovou adresu, pokud vás o to výrobce požádá.'),('2. Otevřete aplikaci a přidejte vozidlo','V aplikaci zvolte přidání vozidla a zadejte VIN podle průvodce. VIN je identifikační číslo vozidla. Samotné založení účtu ještě vozidlo s aplikací nepropojí.'),('3. Dokončete propojení ve vozidle','Postupujte podle pokynů v aplikaci a na obrazovce vozidla. Některé služby vyžadují také ověření hlavního uživatele a samostatnou aktivaci.')],'availability':'Dostupnost funkcí závisí na vozidle, výbavě, softwaru, zemi a příslušné smlouvě či licenci. Heslo účtu, bezpečnostní PIN, párovací kód a kód vozidla jsou odlišné údaje. Nezadávejte je na webu J&S SERVIS.','linkNote':'Zapomenuté heslo obnovte pouze přes oficiální přihlašovací stránku výrobce.','gen3':'My CUPRA: návod pro vozy GEN3','gen4':'My CUPRA: návod GEN4 pro odpovídající Born a Tavascan'},
 'en':{'intro':'Would you like to connect your vehicle to the manufacturer’s app? Select a brand for information about creating an account, signing in and pairing the vehicle. The exact procedure depends on the model, equipment and infotainment system.','need':'To connect the vehicle, you will need a {account} account and the {app} app.','start':'Start here','accountButton':'Sign in or create a {account} account','helpButton':'Open the vehicle-pairing instructions','combinedButton':'Pairing instructions and the {app} app','appButton':'Information and download for the {app} app','steps':[('1. Sign in or create an account','If you already have an account, sign in. Otherwise create one and confirm your email address if requested by the manufacturer.'),('2. Open the app and add the vehicle','In the app, select the option to add a vehicle and enter its VIN as instructed. VIN means vehicle identification number. Creating an account alone does not pair the vehicle with the app.'),('3. Complete pairing in the vehicle','Follow the instructions in the app and on the vehicle display. Some services also require primary-user verification and a separate activation.')],'availability':'Function availability depends on the vehicle, equipment, software, country and applicable contract or licence. The account password, security PIN, pairing code and vehicle code are different credentials. Do not enter them on the J&S SERVIS website.','linkNote':'Recover a forgotten password only through the manufacturer’s official sign-in page.','gen3':'My CUPRA: instructions for GEN3 vehicles','gen4':'My CUPRA: GEN4 instructions for matching Born and Tavascan versions'},
 'de':{'intro':'Möchten Sie Ihr Fahrzeug mit der Hersteller-App verbinden? Wählen Sie eine Marke. Hier finden Sie Hinweise zu Kontoerstellung, Anmeldung und Fahrzeugverknüpfung. Der genaue Ablauf hängt von Modell, Ausstattung und Infotainment ab.','need':'Für die Verbindung benötigen Sie ein {account}-Konto und die App {app}.','start':'Hier beginnen','accountButton':'Anmelden oder {account}-Konto erstellen','helpButton':'Anleitung zur Fahrzeugverbindung öffnen','combinedButton':'Verbindungsanleitung und App {app}','appButton':'Informationen und Download der App {app}','steps':[('1. Anmelden oder Konto erstellen','Wenn Sie bereits ein Konto haben, melden Sie sich an. Andernfalls erstellen Sie ein Konto und bestätigen auf Aufforderung des Herstellers Ihre E-Mail-Adresse.'),('2. App öffnen und Fahrzeug hinzufügen','Wählen Sie in der App „Fahrzeug hinzufügen“ und geben Sie die VIN nach Anleitung ein. VIN bedeutet Fahrzeug-Identifizierungsnummer. Die Kontoerstellung allein verbindet das Fahrzeug noch nicht mit der App.'),('3. Verbindung im Fahrzeug abschließen','Folgen Sie den Hinweisen in der App und auf dem Fahrzeugdisplay. Einige Dienste erfordern zusätzlich die Prüfung des Hauptnutzers und eine gesonderte Aktivierung.')],'availability':'Die Verfügbarkeit hängt von Fahrzeug, Ausstattung, Software, Land sowie Vertrag oder Lizenz ab. Kontopasswort, Sicherheits-PIN, Kopplungscode und Fahrzeugcode sind unterschiedliche Daten. Geben Sie diese nicht auf der Website von J&S SERVIS ein.','linkNote':'Ein vergessenes Passwort setzen Sie ausschließlich über die offizielle Anmeldeseite des Herstellers zurück.','gen3':'My CUPRA: Anleitung für GEN3-Fahrzeuge','gen4':'My CUPRA: GEN4-Anleitung für passende Born- und Tavascan-Ausführungen'}
}
def online_services_content(lang):
 u=ONLINE_UI[lang];brand_names=UI[lang]['brands']
 out='<div class="online-services">'
 for brand in brand_names:
  item=ONLINE_SERVICES[brand];app_url=item.get('app_url')
  fmt=lambda key: u[key].format(account=item['account'],app=item['app'])
  out+=f'<section class="online-brand-panel" id="online-panel-{brand}" data-online-panel="{brand}" hidden><h2 tabindex="-1">{esc(brand_names[brand])}</h2><p class="online-requirements">{esc(fmt("need"))}</p><h3 class="online-start">{esc(u["start"])}</h3><div class="online-actions">'
  out+=f'<a class="online-action" href="{esc(item["account_url"])}" target="_blank" rel="noopener noreferrer">{esc(fmt("accountButton"))}</a>'
  if app_url:out+=f'<a class="online-action online-action-secondary" href="{esc(app_url)}" target="_blank" rel="noopener noreferrer">{esc(fmt("appButton"))}</a>'
  if brand=='cupra':
   out+=f'<a class="online-action" href="{esc(item["help_url"])}" target="_blank" rel="noopener noreferrer">{esc(u["gen3"])}</a><a class="online-action" href="{esc(item["help_url_2"])}" target="_blank" rel="noopener noreferrer">{esc(u["gen4"])}</a>'
  else:out+=f'<a class="online-action" href="{esc(item["help_url"])}" target="_blank" rel="noopener noreferrer">{esc(fmt("helpButton" if app_url else "combinedButton"))}</a>'
  out+='</div><ol class="online-steps">'
  for heading,text in u['steps']:out+=f'<li><h3>{esc(heading)}</h3><p>{esc(text)}</p></li>'
  out+=f'</ol><p class="online-brand-note"><strong>{esc(item["note"][lang])}</strong></p><p>{esc(u["availability"])}</p><p class="online-password-note">{esc(u["linkNote"])}</p></section>'
 return out+'</div>'

WASHER_UI={
 'cs':{
  'intro':'Správná kapalina zajišťuje čistý výhled a chrání ostřikovací soustavu. Vybírejte ji podle ročního období, očekávaných teplot a požadavků vozidla.','titles':['Letní a zimní směs – jaký je rozdíl?','Přechod na zimu: nestačí pouze dolít nádržku','Co může zamrznutí poškodit?','Čím kapalinu ředit a proč dodržovat poměr?','Proč v létě upřednostnit letní kapalinu?','Směs do −20 °C a venkovních −16 °C','Co dělat, když ostřikovače zamrznou?'],
  'typeHeads':['Druh kapaliny','Typické složení','Hlavní účel'],'typeRows':[('Letní','Voda, čisticí tenzidy a podle výrobku rozpouštědla a další pomocné složky.','Odstraňování hmyzu, mastnoty a letních nečistot.'),('Zimní','Voda, nemrznoucí složky – obvykle alkoholy, například etanol nebo isopropanol – a čisticí přísady.','Ochrana proti zamrznutí a odstraňování soli a zimních nečistot.')],'typeNote':'Přesné složení se liší podle výrobku. Letní kapalina ani samotná voda neposkytují spolehlivou ochranu před mrazem.',
  'winterIntro':'Zimní náplň připravte ještě před prvními mrazy:','winterSteps':['Zbytek letní směsi spotřebujte nebo nechte odsát; čerpadlo nenechávejte běžet nasucho.','Doplňte zimní kapalinu s odpovídající mrazuvzdorností.','Krátkým ostřikováním dostaňte zimní směs také do vedení a trysek.','Nezapomeňte na zadní ostřikovač a případné ostřikovače světlometů.'],'winterNote':'Zbytek vody nebo letní kapaliny sníží výslednou ochranu proti mrazu. Údaj na dolitém kanystru proto nemusí odpovídat skutečné směsi v automobilu. V dlouhém vedení k zadnímu sklu navíc může zůstat původní náplň.',
  'damage':['Zamrzlá náplň může poškodit nádržku, čerpadlo, hadičky nebo jejich spoje a způsobit následný únik kapaliny. Při rozpínání ledu může dojít také k prasknutí vedení.','Opakované spouštění zablokovaného čerpadla může vést k jeho poškození. U některých vozů může řídicí jednotka zaznamenat závadu a další činnost čerpadla omezit.'],
  'dilution':['Koncentrát řeďte přesně podle tabulky na obalu. Poměr 1:1 nemusí u různých výrobků znamenat stejnou ochranu proti mrazu.','Hotovou směs používejte bez dalšího ředění, pokud výrobce výslovně nepovoluje jiný postup. Přidáním vody se mění její čisticí vlastnosti i mrazuvzdornost.','Druh vody volte podle návodu vozidla a výrobce kapaliny. Čistá voda omezuje zanášení soustavy nečistotami; vhodnost tvrdé vody závisí také na složení přípravku.','Destilovaná nebo demineralizovaná voda není univerzálním doporučením pro všechny vozy. Některé návody Volkswagen destilovanou vodu výslovně nepovolují.'],'forbidden':'Do ostřikovačů nepřidávejte chladicí kapalinu motoru, prostředek na nádobí ani jiné nepředepsané přípravky. Nevhodná kombinace může zhoršit výhled nebo ucpat trysky.',
  'summer':['Letní přípravky jsou zaměřeny zejména na odstranění hmyzu a dalších letních nečistot. Zimní směsi mají jiné složení a jejich nemrznoucí ochranu v teplém počasí nevyužijete.','Zimní kapalina vhodná pro daný vůz není v létě automaticky škodlivá ani zakázaná. Některé koncentráty mají výrobcem předepsané také letní ředění. Rozhoduje konkrétní výrobek a jeho návod.'],
  'temperature':['Vyšší rychlost sama o sobě neznamená, že taková směs musí zamrznout. Proudící vzduch urychluje ochlazování, ale samotným prouděním neochladí kapalinu pod skutečnou teplotu okolního vzduchu. Ani malý průměr hadiček nemění bod tuhnutí směsi.','Přesto může ostřikování v mrazu selhávat. Rozhoduje skutečné naředění, zbytky vody v soustavě a vhodnost kapaliny pro konkrétní trysky. Ochrana náplně proti zamrznutí nemusí být totožná s teplotním limitem správného rozprašování ve vějířových tryskách. Výrobce může uvádět oba údaje zvlášť.'],
  'frozen':['Ostřikovače opakovaně nespouštějte.','Nechte celou soustavu pozvolna rozmrznout v prostoru s teplotou nad nulou.','Nepoužívejte horkovzdušnou pistoli ani jiný intenzivní zdroj tepla.','Po rozmrznutí upravte nebo vyměňte náplň a ověřte funkci i těsnost systému.'],'recommend':'Doporučení J&S SERVIS: Před zimou připravte náplň s dostatečnou teplotní rezervou a ověřte její vhodnost pro dané trysky. Pokud ostřikování nefunguje a nelze udržet bezpečný výhled, v jízdě nepokračujte.'},
 'en':{
  'intro':'The correct washer fluid maintains a clear view and protects the washer system. Select it for the season, expected temperatures and vehicle requirements.','titles':['Summer and winter fluid – what is the difference?','Preparing for winter: topping up the reservoir is not enough','What can freezing damage?','What should be used for dilution and why follow the ratio?','Why prefer summer fluid in summer?','Fluid rated to −20 °C at an outside temperature of −16 °C','What should you do if the washers freeze?'],
  'typeHeads':['Fluid type','Typical composition','Main purpose'],'typeRows':[('Summer','Water, cleaning surfactants and, depending on the product, solvents and other auxiliary ingredients.','Removing insects, grease and summer dirt.'),('Winter','Water, antifreeze components – usually alcohols such as ethanol or isopropanol – and cleaning additives.','Protection against freezing and removal of salt and winter dirt.')],'typeNote':'The exact composition varies by product. Summer fluid and water alone do not provide reliable frost protection.',
  'winterIntro':'Prepare the winter fill before the first frost:','winterSteps':['Use up or have the remaining summer fluid extracted; do not run the pump dry.','Add winter fluid with suitable frost protection.','Operate the washers briefly to move the winter fluid into the lines and nozzles.','Remember the rear washer and any headlamp washers.'],'winterNote':'Remaining water or summer fluid reduces the resulting frost protection, so the value on the added container may not match the actual mixture in the vehicle. The old fill can also remain in the long line to the rear window.',
  'damage':['Frozen fluid can damage the reservoir, pump, hoses or their joints and cause a subsequent leak. Expanding ice can also rupture a line.','Repeatedly operating a blocked pump can damage it. On some vehicles the control unit can record a fault and restrict further pump operation.'],
  'dilution':['Dilute concentrate exactly to the table on its container. A 1:1 ratio does not necessarily provide the same frost protection for different products.','Use ready-mixed fluid without further dilution unless the manufacturer expressly permits otherwise. Adding water changes cleaning performance and frost protection.','Select the water type under the instructions of the vehicle and fluid manufacturer. Clean water limits contamination of the system; suitability of hard water also depends on the product formulation.','Distilled or demineralised water is not a universal recommendation for every vehicle. Some Volkswagen manuals expressly do not permit distilled water.'],'forbidden':'Do not add engine coolant, washing-up liquid or other unspecified products to the washer system. An unsuitable combination can impair visibility or block the nozzles.',
  'summer':['Summer products principally target insects and other summer dirt. Winter fluids have a different formulation, and their antifreeze protection is not needed in warm weather.','A winter fluid suitable for the vehicle is not automatically harmful or prohibited in summer. Some concentrates also have a manufacturer-specified summer dilution. The exact product and its instructions govern.'],
  'temperature':['Higher speed alone does not mean such a mixture must freeze. Moving air accelerates cooling but does not by itself cool the fluid below the actual ambient temperature. A small hose diameter does not change the mixture’s freezing point.','Washer operation can still fail in frost. The actual dilution, residual water and suitability for the exact nozzles matter. Fill frost protection need not equal the temperature limit for correct atomisation by fan nozzles; a manufacturer may state both values separately.'],
  'frozen':['Do not operate the washers repeatedly.','Allow the whole system to thaw gradually in a space above freezing.','Do not use a heat gun or another intense heat source.','After thawing, adjust or replace the fill and verify operation and system tightness.'],'recommend':'J&S SERVIS recommendation: Before winter, prepare fluid with an adequate temperature margin and verify suitability for the fitted nozzles. If the washers do not work and a safe view cannot be maintained, do not continue driving.'},
 'de':{
  'intro':'Die richtige Scheibenwaschflüssigkeit sorgt für klare Sicht und schützt die Waschanlage. Nach Jahreszeit, erwarteten Temperaturen und Fahrzeuganforderungen auswählen.','titles':['Sommer- und Wintermischung – was ist der Unterschied?','Umstellung auf Winter: bloßes Auffüllen reicht nicht','Was kann durch Einfrieren beschädigt werden?','Womit verdünnen und warum das Verhältnis einhalten?','Warum im Sommer Sommerreiniger bevorzugen?','Mischung bis −20 °C bei −16 °C Außentemperatur','Was tun, wenn die Waschanlage eingefroren ist?'],
  'typeHeads':['Flüssigkeitsart','Typische Zusammensetzung','Hauptzweck'],'typeRows':[('Sommer','Wasser, Reinigungstenside und je nach Produkt Lösungsmittel sowie weitere Hilfsstoffe.','Entfernung von Insekten, Fett und Sommerschmutz.'),('Winter','Wasser, Frostschutzbestandteile – meist Alkohole wie Ethanol oder Isopropanol – und Reinigungszusätze.','Frostschutz und Entfernung von Salz und Winterschmutz.')],'typeNote':'Die genaue Zusammensetzung unterscheidet sich je nach Produkt. Sommerreiniger oder Wasser allein bieten keinen zuverlässigen Frostschutz.',
  'winterIntro':'Die Winterfüllung vor dem ersten Frost vorbereiten:','winterSteps':['Restlichen Sommerreiniger verbrauchen oder absaugen lassen; die Pumpe nicht trocken laufen lassen.','Winterreiniger mit passendem Frostschutz einfüllen.','Durch kurzes Betätigen Winterreiniger auch in Leitungen und Düsen bringen.','Heckscheiben- und gegebenenfalls Scheinwerferwaschanlage nicht vergessen.'],'winterNote':'Wasser- oder Sommerreinigerreste verringern den resultierenden Frostschutz. Der Wert auf dem nachgefüllten Kanister muss daher nicht der tatsächlichen Mischung im Fahrzeug entsprechen. In der langen Leitung zur Heckscheibe kann die alte Füllung verbleiben.',
  'damage':['Gefrorene Flüssigkeit kann Behälter, Pumpe, Schläuche oder Verbindungen beschädigen und später Undichtigkeiten verursachen. Sich ausdehnendes Eis kann auch Leitungen reißen lassen.','Wiederholtes Betätigen einer blockierten Pumpe kann sie beschädigen. Bei manchen Fahrzeugen kann das Steuergerät einen Fehler speichern und die weitere Pumpenfunktion begrenzen.'],
  'dilution':['Konzentrat genau nach der Tabelle auf dem Gebinde verdünnen. Ein Verhältnis 1:1 bedeutet bei unterschiedlichen Produkten nicht zwingend den gleichen Frostschutz.','Fertigmischung ohne weitere Verdünnung verwenden, sofern der Hersteller nichts anderes ausdrücklich erlaubt. Wasser verändert Reinigungswirkung und Frostschutz.','Die Wasserart nach Fahrzeug- und Produkthinweisen wählen. Sauberes Wasser begrenzt Verunreinigungen; die Eignung harten Wassers hängt auch von der Produktformulierung ab.','Destilliertes oder demineralisiertes Wasser ist keine allgemeine Empfehlung für alle Fahrzeuge. Einige Volkswagen-Anleitungen erlauben destilliertes Wasser ausdrücklich nicht.'],'forbidden':'Kein Motorkühlmittel, Spülmittel oder andere nicht vorgeschriebene Mittel in die Waschanlage geben. Eine ungeeignete Kombination kann die Sicht verschlechtern oder Düsen verstopfen.',
  'summer':['Sommerprodukte sind besonders auf Insekten und anderen Sommerschmutz ausgerichtet. Wintermischungen sind anders zusammengesetzt; ihr Frostschutz wird bei warmem Wetter nicht benötigt.','Ein für das Fahrzeug geeigneter Winterreiniger ist im Sommer nicht automatisch schädlich oder verboten. Für manche Konzentrate schreibt der Hersteller auch eine Sommerverdünnung vor. Produkt und Anleitung entscheiden.'],
  'temperature':['Höhere Geschwindigkeit allein bedeutet nicht, dass eine solche Mischung einfrieren muss. Strömende Luft beschleunigt die Abkühlung, kühlt die Flüssigkeit jedoch nicht unter die tatsächliche Umgebungstemperatur. Auch ein kleiner Schlauchdurchmesser verändert den Gefrierpunkt nicht.','Die Waschanlage kann bei Frost trotzdem ausfallen. Tatsächliche Verdünnung, Restwasser und Eignung für die konkreten Düsen entscheiden. Der Frostschutz der Füllung muss nicht dem Temperaturlimit für korrektes Zerstäuben in Fächerdüsen entsprechen; der Hersteller kann beide Werte getrennt angeben.'],
  'frozen':['Waschanlage nicht wiederholt betätigen.','Die gesamte Anlage in einem Raum über null Grad langsam auftauen lassen.','Keine Heißluftpistole oder andere starke Wärmequelle verwenden.','Nach dem Auftauen Füllung anpassen oder ersetzen sowie Funktion und Dichtheit prüfen.'],'recommend':'Empfehlung von J&S SERVIS: Vor dem Winter eine Füllung mit ausreichender Temperaturreserve vorbereiten und die Eignung für die verbauten Düsen prüfen. Funktioniert die Waschanlage nicht und lässt sich eine sichere Sicht nicht erhalten, nicht weiterfahren.'}
}

def washer_content(lang):
 u=WASHER_UI[lang]
 def paragraphs(items):return "".join(f'<p>{esc(x)}</p>' for x in items)
 def detail(title,body):return f'<details class="washer-section"><summary><span>{esc(title)}</span><span class="wl-group-arrow" aria-hidden="true"></span></summary><div class="washer-section-body">{body}</div></details>'
 heads=u["typeHeads"];table='<table class="washer-table"><thead><tr>'+"".join(f'<th scope="col">{esc(x)}</th>' for x in heads)+'</tr></thead><tbody>'
 for row in u["typeRows"]:table+='<tr>'+"".join(f'<td data-label="{esc(label)}">{esc(value)}</td>' for label,value in zip(heads,row))+'</tr>'
 table+='</tbody></table>'
 types=table+f'<p class="washer-note">{esc(u["typeNote"])}</p>'
 winter=f'<p>{esc(u["winterIntro"])}</p><ul class="washer-points">'+"".join(f'<li>{esc(x)}</li>' for x in u["winterSteps"])+f'</ul><p class="washer-note">{esc(u["winterNote"])}</p>'
 dilution=paragraphs(u["dilution"])+f'<aside class="washer-forbidden" role="note">{esc(u["forbidden"])}</aside>'
 frozen='<ul class="washer-points">'+"".join(f'<li>{esc(x)}</li>' for x in u["frozen"])+"</ul>"
 bodies=[types,winter,paragraphs(u["damage"]),dilution,paragraphs(u["summer"]),paragraphs(u["temperature"]),frozen]
 accordion="".join(detail(a,b) for a,b in zip(u["titles"],bodies))
 return f'<div class="washer-guide"><p class="washer-intro">{esc(u["intro"])}</p><div class="washer-accordion">{accordion}</div><aside class="washer-recommendation" role="note">{esc(u["recommend"])}</aside></div>'

FUELS_UI={
 'cs':{
  'intro':'Správné palivo vybírejte podle požadavků konkrétního motoru. Rozhoduje předepsaná norma, oktanové číslo a schválené složení paliva.','titles':['Jaké palivo patří do mého vozu?','Benzín – co znamená oktanové číslo?','Nafta – co znamená cetanové číslo?','Proč pravidelně nedojíždět na rezervu?','Má smysl používat aditiva?','Natankovali jste nesprávné palivo?'],
  'selectionIntro':'Údaje najdete zpravidla na vnitřní straně víčka palivové nádrže a v návodu k obsluze. Samotný název modelu nebo označení TSI, TFSI či TDI k přesnému výběru nestačí.','fuelHeads':['Palivo','Norma a označení','Co sledovat'],'fuelRows':[('Bezolovnatý benzín','ČSN EN 228, E5 nebo E10','Předepsané oktanové číslo a povolený obsah etanolu.'),('Motorová nafta B7','ČSN EN 590','Běžné palivo pro dieselové motory, pokud jej výrobce předepisuje.'),('Parafinická nafta, například HVO100','ČSN EN 15940, XTL','Pouze pro vozidla, která mají použití výslovně schválené výrobcem.')],'labels':['E5 a E10 označují benzín s maximálně 5 nebo 10 % objemu etanolu. B7 znamená naftu s maximálně 7 % objemu biosložky FAME. Tato označení nevyjadřují oktanové ani cetanové číslo.','U starších vozů ověřte kompatibilitu s E10. Benzín s vyšším oktanovým číslem není automaticky E5 – vždy kontrolujte označení na stojanu.'],
  'octaneIntro':'Oktanové číslo vyjadřuje odolnost benzínu proti klepání při spalování. V Evropě se používá označení RON, například 95, 98 nebo 100.','octaneTitle':'Příklady údajů na štítku','octaneHeads':['Údaj na vozidle','Jak jej číst'],'octaneRows':[('95 / min. 91 RON','Doporučený je benzín 95; výrobce připouští nejméně 91 podle podmínek v návodu.'),('min. 95 RON','Používejte benzín s oktanovým číslem alespoň 95.'),('98 / min. 95 RON','Doporučený je benzín 98; povolený je také 95, případně s mírným snížením výkonu.')],'octaneNotes':['Doporučená hodnota a povolené minimum nejsou totéž. Nouzové použití paliva s nižším oktanovým číslem se řídí výhradně návodem konkrétního vozidla.','Benzín 98 nebo 100 může pomoci motorům, které jeho vlastnosti dokážou využít. Vyšší oktanové číslo však samo o sobě nezaručuje vyšší výkon ani nižší spotřebu u každého vozu.'],
  'cetane':['Cetanové číslo vyjadřuje schopnost nafty vznítit se po vstříknutí do stlačeného horkého vzduchu. Vyšší hodnota zpravidla znamená kratší prodlevu vznícení a může příznivě ovlivnit studené starty a hlučnost spalování.','U nafty podle ČSN EN 590 je minimální cetanové číslo 51. Nejde však o jediný ukazatel kvality – důležité jsou také čistota, mazivost a vlastnosti při nízkých teplotách.'],
  'reserveIntro':'Palivo doporučujeme doplňovat s předstihem, ideálně ještě před rozsvícením rezervy.','reserve':[('Regenerace DPF','Nízká hladina paliva může podle provedení vozidla regeneraci omezit nebo přerušit. Pokud současně svítí kontrolka DPF a rezervy, před předepsanou regenerační jízdou nejprve natankujte.'),('Palivové nezávislé topení','Při nízké hladině se nemusí spustit nebo se předčasně vypne. Nemusí tedy jít o závadu topení. Konkrétní podmínky určuje návod vozidla.')],'reserveNote':'Nádrž nevyjíždějte úplně. Úplné vyčerpání paliva může způsobit nepravidelný chod nebo zastavení motoru.',
  'additiveIntro':'Vhodná aditivace může mít přínos. Palivo upravené výrobcem a přísada dodatečně nalitá do nádrže ale nejsou automaticky zaměnitelné.','additiveHeads':['Možné přínosy vhodné aditivace','Rizika nevhodného použití'],'additiveRows':[('Udržování čistoty palivového systému a omezení úsad.','Neschválený přípravek může poškodit motor nebo emisní systém.'),('Ochrana proti korozi.','Kovové oktanové přísady mohou poškodit motor a katalyzátor.'),('Zlepšení zapalovacích nebo nízkoteplotních vlastností nafty.','Nevhodná kombinace zimních přísad může zhoršit filtrovatelnost paliva.')],'additiveNotes':['Tyto účinky závisí na složení paliva a konkrétní přísadě. Nelze je slíbit u každého přípravku.','Dodatečná aditiva používejte pouze tehdy, pokud je výrobce pro konkrétní vůz připouští. Některé návody jejich přidávání do nafty výslovně zakazují. U povoleného přípravku dodržujte dávkování a nekombinujte jej s dalšími přísadami bez ověření kompatibility.','Pro zimní provoz tankujte naftu odpovídající očekávaným teplotám. Naftu nikdy neřeďte benzínem.'],'recommend':'Doporučení J&S SERVIS: Základem je palivo odpovídající předpisu vozidla, včasné tankování a pravidelný servis. Vhodnost dodatečného aditiva posuzujte podle konkrétního motoru a účelu použití.','wrong':'Motor nestartujte a kontaktujte servis nebo asistenční službu. Pokud motor již běží, bezpečně zastavte a vypněte jej. Další jízdou může rozsah poškození výrazně narůst.'},
 'en':{
  'intro':'Choose fuel according to the requirements of the exact engine. The prescribed standard, octane rating and approved fuel composition govern.','titles':['Which fuel belongs in my vehicle?','Petrol – what does the octane rating mean?','Diesel – what does the cetane number mean?','Why avoid regularly driving into the reserve?','Do fuel additives make sense?','Have you filled with the wrong fuel?'],
  'selectionIntro':'The information is usually inside the fuel-filler flap and in the owner’s manual. A model name or the designation TSI, TFSI or TDI alone is not enough for an exact choice.','fuelHeads':['Fuel','Standard and label','What to check'],'fuelRows':[('Unleaded petrol','EN 228, E5 or E10','Prescribed octane rating and permitted ethanol content.'),('B7 diesel','EN 590','Normal diesel fuel where prescribed by the manufacturer.'),('Paraffinic diesel, such as HVO100','EN 15940, XTL','Only for vehicles whose manufacturer expressly approves its use.')],'labels':['E5 and E10 mean petrol containing no more than 5% or 10% ethanol by volume. B7 means diesel containing no more than 7% FAME by volume. These labels do not state the octane or cetane number.','For older vehicles, verify E10 compatibility. Higher-octane petrol is not automatically E5; always check the pump label.'],
  'octaneIntro':'The octane rating describes petrol’s resistance to combustion knock. Europe uses the RON designation, for example 95, 98 or 100.','octaneTitle':'Examples of vehicle label information','octaneHeads':['Vehicle information','How to read it'],'octaneRows':[('95 / min. 91 RON','95 petrol is recommended; the manufacturer permits at least 91 under the conditions in the manual.'),('min. 95 RON','Use petrol with an octane rating of at least 95.'),('98 / min. 95 RON','98 petrol is recommended; 95 is also permitted, possibly with a slight reduction in performance.')],'octaneNotes':['A recommended value and a permitted minimum are not the same. Emergency use of lower-octane fuel is governed solely by the exact vehicle manual.','98 or 100 petrol can benefit engines able to use its properties. A higher octane rating alone does not guarantee more power or lower consumption in every vehicle.'],
  'cetane':['The cetane number describes diesel fuel’s ability to ignite after injection into hot compressed air. A higher value generally means a shorter ignition delay and can benefit cold starting and combustion noise.','Diesel meeting EN 590 has a minimum cetane number of 51. It is not the only quality measure; cleanliness, lubricity and low-temperature properties also matter.'],
  'reserveIntro':'We recommend refuelling in good time, ideally before the reserve warning comes on.','reserve':[('DPF regeneration','Depending on the vehicle, a low fuel level can restrict or interrupt regeneration. If both the DPF and reserve warnings are on, refuel before attempting the prescribed regeneration drive.'),('Fuel-operated auxiliary heater','At a low fuel level it may not start or may switch off early. This need not indicate a heater fault. The vehicle manual defines the exact conditions.')],'reserveNote':'Do not run the tank completely dry. Fuel exhaustion can cause irregular running or stop the engine.',
  'additiveIntro':'Suitable additive treatment can have benefits. Fuel treated by its producer and an additive poured into the tank later are not automatically interchangeable.','additiveHeads':['Possible benefits of suitable treatment','Risks of unsuitable use'],'additiveRows':[('Keeping the fuel system clean and limiting deposits.','An unapproved product can damage the engine or emissions system.'),('Protection against corrosion.','Metallic octane additives can damage the engine and catalytic converter.'),('Improving diesel ignition or low-temperature properties.','An unsuitable combination of winter additives can impair fuel filterability.')],'additiveNotes':['Effects depend on the fuel composition and exact additive and cannot be promised for every product.','Use aftermarket additives only where the manufacturer permits them for the exact vehicle. Some manuals expressly prohibit adding them to diesel. Follow the dose for an approved product and do not combine additives without verifying compatibility.','For winter operation, use diesel suitable for the expected temperatures. Never dilute diesel with petrol.'],'recommend':'J&S SERVIS recommendation: Start with fuel that meets the vehicle specification, refuel in good time and maintain the vehicle regularly. Assess an aftermarket additive for the exact engine and intended purpose.','wrong':'Do not start the engine; contact a workshop or roadside assistance. If the engine is already running, stop safely and switch it off. Further driving can greatly increase the damage.'},
 'de':{
  'intro':'Den Kraftstoff nach den Anforderungen des konkreten Motors wählen. Maßgeblich sind vorgeschriebene Norm, Oktanzahl und freigegebene Kraftstoffzusammensetzung.','titles':['Welcher Kraftstoff gehört in mein Fahrzeug?','Benzin – was bedeutet die Oktanzahl?','Diesel – was bedeutet die Cetanzahl?','Warum nicht regelmäßig bis zur Reserve fahren?','Sind Kraftstoffzusätze sinnvoll?','Falschen Kraftstoff getankt?'],
  'selectionIntro':'Die Angaben stehen üblicherweise an der Innenseite der Tankklappe und in der Betriebsanleitung. Modellname oder die Bezeichnung TSI, TFSI beziehungsweise TDI allein reichen für die genaue Auswahl nicht aus.','fuelHeads':['Kraftstoff','Norm und Kennzeichnung','Worauf achten?'],'fuelRows':[('Bleifreies Benzin','EN 228, E5 oder E10','Vorgeschriebene Oktanzahl und zulässiger Ethanolanteil.'),('Dieselkraftstoff B7','EN 590','Üblicher Dieselkraftstoff, sofern vom Hersteller vorgeschrieben.'),('Paraffinischer Diesel, zum Beispiel HVO100','EN 15940, XTL','Nur für Fahrzeuge mit ausdrücklicher Herstellerfreigabe.')],'labels':['E5 und E10 bezeichnen Benzin mit höchstens 5 beziehungsweise 10 Volumenprozent Ethanol. B7 bedeutet Diesel mit höchstens 7 Volumenprozent FAME. Diese Kennzeichnungen geben weder Oktan- noch Cetanzahl an.','Bei älteren Fahrzeugen die E10-Verträglichkeit prüfen. Benzin mit höherer Oktanzahl ist nicht automatisch E5; immer die Zapfsäulenkennzeichnung beachten.'],
  'octaneIntro':'Die Oktanzahl beschreibt die Klopffestigkeit von Benzin. In Europa wird RON verwendet, beispielsweise 95, 98 oder 100.','octaneTitle':'Beispiele für Angaben am Fahrzeug','octaneHeads':['Fahrzeugangabe','Bedeutung'],'octaneRows':[('95 / min. 91 RON','Benzin 95 wird empfohlen; mindestens 91 ist nach den Bedingungen der Anleitung zulässig.'),('min. 95 RON','Benzin mit mindestens 95 Oktan verwenden.'),('98 / min. 95 RON','Benzin 98 wird empfohlen; 95 ist ebenfalls zulässig, gegebenenfalls mit geringer Leistungsminderung.')],'octaneNotes':['Empfehlung und zulässiger Mindestwert sind nicht dasselbe. Eine Notverwendung niedrigerer Oktanzahl richtet sich ausschließlich nach der konkreten Fahrzeuganleitung.','Benzin 98 oder 100 kann Motoren nützen, die seine Eigenschaften verwerten. Eine höhere Oktanzahl allein garantiert nicht bei jedem Fahrzeug mehr Leistung oder weniger Verbrauch.'],
  'cetane':['Die Cetanzahl beschreibt die Zündwilligkeit von Diesel nach der Einspritzung in heiße verdichtete Luft. Ein höherer Wert bedeutet üblicherweise kürzeren Zündverzug und kann Kaltstart sowie Verbrennungsgeräusch verbessern.','Diesel nach EN 590 hat eine Mindestcetanzahl von 51. Sie ist nicht das einzige Qualitätsmerkmal; auch Reinheit, Schmierfähigkeit und Kälteeigenschaften sind wichtig.'],
  'reserveIntro':'Wir empfehlen rechtzeitiges Tanken, möglichst noch vor dem Aufleuchten der Reservewarnung.','reserve':[('DPF-Regeneration','Je nach Fahrzeug kann ein niedriger Kraftstoffstand die Regeneration einschränken oder unterbrechen. Leuchten DPF- und Reservewarnung gleichzeitig, vor der vorgeschriebenen Regenerationsfahrt zuerst tanken.'),('Kraftstoffbetriebene Standheizung','Bei niedrigem Stand startet sie möglicherweise nicht oder schaltet vorzeitig ab. Dies muss kein Heizungsfehler sein. Die genauen Bedingungen stehen in der Fahrzeuganleitung.')],'reserveNote':'Den Tank nicht vollständig leerfahren. Kraftstoffmangel kann unrunden Lauf oder Motorstillstand verursachen.',
  'additiveIntro':'Eine geeignete Additivierung kann Vorteile haben. Vom Kraftstoffhersteller behandelter Kraftstoff und ein später in den Tank gefüllter Zusatz sind jedoch nicht automatisch austauschbar.','additiveHeads':['Mögliche Vorteile geeigneter Additivierung','Risiken ungeeigneter Verwendung'],'additiveRows':[('Kraftstoffsystem sauber halten und Ablagerungen begrenzen.','Ein nicht freigegebenes Produkt kann Motor oder Abgassystem beschädigen.'),('Korrosionsschutz.','Metallische Oktanzusätze können Motor und Katalysator beschädigen.'),('Zünd- oder Kälteeigenschaften von Diesel verbessern.','Eine ungeeignete Kombination von Winterzusätzen kann die Filtrierbarkeit verschlechtern.')],'additiveNotes':['Die Wirkungen hängen von Kraftstoff und Zusatz ab und können nicht für jedes Produkt zugesichert werden.','Nachträgliche Zusätze nur verwenden, wenn der Hersteller sie für das konkrete Fahrzeug zulässt. Manche Anleitungen verbieten ausdrücklich Zusätze im Diesel. Bei einem zulässigen Produkt Dosierung beachten und Zusätze nicht ohne Verträglichkeitsprüfung kombinieren.','Für den Winter Diesel passend zu den erwarteten Temperaturen tanken. Diesel niemals mit Benzin verdünnen.'],'recommend':'Empfehlung von J&S SERVIS: Grundlage sind Kraftstoff nach Fahrzeugvorgabe, rechtzeitiges Tanken und regelmäßiger Service. Einen zusätzlichen Kraftstoffzusatz nach konkretem Motor und Verwendungszweck beurteilen.','wrong':'Motor nicht starten und Werkstatt oder Pannenhilfe kontaktieren. Läuft der Motor bereits, sicher anhalten und ausschalten. Weiterfahrt kann den Schaden erheblich vergrößern.'}
}

def fuels_content(lang):
 u=FUELS_UI[lang]
 def paragraphs(items):return "".join(f'<p>{esc(x)}</p>' for x in items)
 def table(heads,rows,extra):
  out=f'<table class="fuels-table {extra}"><thead><tr>'+"".join(f'<th scope="col">{esc(x)}</th>' for x in heads)+'</tr></thead><tbody>'
  for row in rows:out+='<tr>'+"".join(f'<td data-label="{esc(label)}">{esc(value)}</td>' for label,value in zip(heads,row))+'</tr>'
  return out+'</tbody></table>'
 def detail(title,body):return f'<details class="fuels-section"><summary><span>{esc(title)}</span><span class="wl-group-arrow" aria-hidden="true"></span></summary><div class="fuels-section-body">{body}</div></details>'
 selection=f'<p>{esc(u["selectionIntro"])}</p>'+table(u["fuelHeads"],u["fuelRows"],"fuels-selection-table")+paragraphs(u["labels"])
 octane=f'<p>{esc(u["octaneIntro"])}</p><h3>{esc(u["octaneTitle"])}</h3>'+table(u["octaneHeads"],u["octaneRows"],"fuels-octane-table")+paragraphs(u["octaneNotes"])
 reserve=f'<p>{esc(u["reserveIntro"])}</p><dl class="fuels-fact-list">'+"".join(f'<div><dt>{esc(a)}</dt><dd>{esc(b)}</dd></div>' for a,b in u["reserve"])+f'</dl><p class="fuels-note">{esc(u["reserveNote"])}</p>'
 additives=f'<p>{esc(u["additiveIntro"])}</p>'+table(u["additiveHeads"],u["additiveRows"],"fuels-additives-table")+paragraphs(u["additiveNotes"])+f'<aside class="fuels-recommendation" role="note">{esc(u["recommend"])}</aside>'
 wrong=f'<aside class="fuels-wrong-warning" role="alert">{esc(u["wrong"])}</aside>'
 bodies=[selection,octane,paragraphs(u["cetane"]),reserve,additives,wrong]
 return f'<div class="fuels-guide"><p class="fuels-intro">{esc(u["intro"])}</p><div class="fuels-accordion">'+"".join(detail(a,b) for a,b in zip(u["titles"],bodies))+'</div></div>'

EMISSIONS_UI={
 'cs':{
  'intro':'Filtry DPF a GPF/OPF zachycují pevné částice. AdBlue pomáhá systému SCR snižovat emise oxidů dusíku. Každý systém má jinou funkci a vyžaduje jiný postup při rozsvícení kontrolky.',
  'titles':['DPF a GPF/OPF – co znamená rozsvícená kontrolka?','Jak podpořit regeneraci za jízdy?','Kontrolka nezhasla nebo svítí další výstrahy?','Životnost DPF – zkušenosti J&S SERVIS','AdBlue – funkce, norma a složení','Jak správně doplnit AdBlue?','Co se stane, když AdBlue nedoplníte?'],
  'filters':['DPF je filtr pevných částic dieselových motorů. GPF/OPF označuje filtr pevných částic benzínových motorů.','Při běžném provozu se zachycené saze průběžně spalují – probíhá regenerace. Časté krátké jízdy mohou její dokončení znemožnit. Rozsvícená kontrolka filtru proto může vyzývat k regenerační jízdě.'],
  'regenIntro':['Motor musí být zahřátý. Přesný postup vždy ověřte v návodu svého vozidla – rychlost, otáčky i délka jízdy se podle motoru liší.'],'regenTitle':'Příklady postupů z návodu vybraných vozů Audi','regenHeads':['Filtr','Doporučený postup'],'regenRows':[('Diesel – DPF','Jeďte alespoň 60 km/h při nejméně 2 000 ot./min. Regenerace může trvat přibližně 20–40 minut. Úspěšné dokončení signalizuje zhasnutí kontrolky.'),('Benzín – GPF/OPF','Zrychlete alespoň na 80 km/h, následně na několik sekund zcela uvolněte plyn a nechte vůz zpomalovat se zařazeným rychlostním stupněm. Postup podle návodu opakujte do zhasnutí kontrolky.')],'regenNote':'Dodržujte rychlostní limity a přizpůsobte jízdu provozu i počasí. Uvedené postupy nejsou univerzálním návodem pro všechny vozy VW Group.','heat':'Během regenerace se mohou zvýšit volnoběžné otáčky, objevit zápach nebo běžet ventilátor i po vypnutí motoru. Kvůli vysoké teplotě výfuku neparkujte nad suchou trávou ani jinými hořlavými materiály.',
  'warnings':['Pokud kontrolka po jízdě provedené podle návodu nezhasne nebo se opakovaně vrací, objednejte vůz na diagnostiku.','Pokud současně svítí další výstrahy, bliká kontrolka žhavení či motoru nebo vůz ztrácí výkon, nepokoušejte se problém řešit další regenerační jízdou. Kontaktujte servis nebo asistenční službu.','Při červené výstraze postupujte podle pokynů vozidla a bezpečně zastavte.'],
  'life':['Z naší servisní praxe se u některých dieselových vozů kolem 250 000 km setkáváme s DPF na hranici životnosti. Nejde však o pevný interval výměny.','Saze se při regeneraci spalují, ale nespalitelný popel ve filtru zůstává. O vhodnosti odborného čištění nebo nutnosti výměny rozhoduje skutečný stav filtru, diagnostika a postup výrobce. Tento nájezd nelze automaticky vztahovat na benzínové GPF/OPF.'],
  'adblueIntro':'AdBlue se vstřikuje do výfukového systému dieselových vozů vybavených SCR, kde pomáhá snižovat emise oxidů dusíku. Má samostatnou nádrž.','adblueHeads':['Údaj','Specifikace'],'adblueRows':[('Norma kvality','ISO 22241-1, součást řady ISO 22241'),('Označení roztoku','AUS 32, také DEF'),('Vysoce čistá syntetická močovina','32,5 % hmotnosti'),('Demineralizovaná voda','67,5 % hmotnosti')],'adblueNote':'Jde o hmotnostní složení, nikoli poměr objemů v litrech.',
  'refill':['Zaparkujte na rovině a vypněte motor i zapalování.','Použijte hotové AdBlue splňující ISO 22241-1.','Dodržte minimální a maximální doplňované množství uvedené na displeji nebo v návodu.','Při použití vhodné čerpací pistole ukončete plnění po jejím prvním automatickém vypnutí.'],'refillWarning':'AdBlue neřeďte vodou, nepřidávejte přísady a nikdy jej nelijte do palivové nádrže. Při záměně kapalin motor nestartujte a kontaktujte servis.',
  'empty':['Vozidlo upozorňuje na nízkou zásobu a zobrazuje zbývající dojezd.','Běžící motor se kvůli samotnému vyčerpání AdBlue automaticky nevypne. Po dosažení nulového dojezdu však po vypnutí nebude možné znovu nastartovat. Doplnění proto neodkládejte až na poslední kilometry.'],'recognitionTitle':'Doplnili jste AdBlue, ale hlášení nezmizelo?','recognition':['Rozpoznání doplnění může chvíli trvat. U některých vozů je nutné po doplnění nejprve zapnout pouze zapalování a přibližně 30 sekund počkat, než motor nastartujete. Rozhodující je postup v návodu konkrétního vozidla.','Po uplynutí zobrazeného dojezdu a aktivaci zákazu startu u některých modelů pouhé dolití AdBlue nestačí. Možnost startu je nutné znovu aktivovat diagnostikou podle postupu výrobce; některá provedení vyžadují také diagnostické přizpůsobení hladiny. Pokud zákaz startu přetrvává nebo displej hlásí závadu SCR/AdBlue, je nutná diagnostika a odstranění příčiny. Samotné doplnění kapaliny závadu systému neodstraní.']},
 'en':{
  'intro':'DPF and GPF/OPF filters trap particulate matter. AdBlue helps the SCR system reduce nitrogen-oxide emissions. Each system has a different function and requires a different response when a warning light comes on.',
  'titles':['DPF and GPF/OPF – what does the warning light mean?','How can regeneration be supported while driving?','The light stayed on or other warnings appeared','DPF service life – J&S SERVIS experience','AdBlue – function, standard and composition','How to top up AdBlue correctly','What happens if AdBlue is not topped up?'],
  'filters':['DPF is the particulate filter for diesel engines. GPF/OPF denotes the particulate filter for petrol engines.','In normal operation, trapped soot is progressively burned off during regeneration. Frequent short journeys can prevent completion. The filter warning light can therefore request a regeneration drive.'],
  'regenIntro':['The engine must be warm. Always verify the exact procedure in your vehicle manual; speed, engine speed and driving time vary by engine.'],'regenTitle':'Examples from manuals for selected Audi vehicles','regenHeads':['Filter','Recommended procedure'],'regenRows':[('Diesel – DPF','Drive at least 60 km/h at no less than 2,000 rpm. Regeneration can take approximately 20–40 minutes. The warning light going out indicates successful completion.'),('Petrol – GPF/OPF','Accelerate to at least 80 km/h, then fully release the accelerator for several seconds and allow the vehicle to slow in gear. Repeat as directed by the manual until the light goes out.')],'regenNote':'Observe speed limits and adapt to traffic and weather. These examples are not universal instructions for every Volkswagen Group vehicle.','heat':'During regeneration, idle speed may rise, an odour may occur, or the fan may continue after the engine is switched off. Because of the high exhaust temperature, do not park over dry grass or other combustible material.',
  'warnings':['If the light does not go out after driving as instructed, or repeatedly returns, book the vehicle for diagnosis.','If other warnings are on, the glow-plug or engine light flashes, or the vehicle loses power, do not attempt another regeneration drive. Contact a workshop or roadside assistance.','For a red warning, follow the vehicle instructions and stop safely.'],
  'life':['In our workshop experience, the DPF in some diesel vehicles is near the end of its service life at around 250,000 km. This is not a fixed replacement interval.','Soot burns during regeneration, but non-combustible ash remains in the filter. Actual filter condition, diagnosis and the manufacturer procedure determine whether professional cleaning or replacement is appropriate. This mileage must not automatically be applied to petrol GPF/OPF filters.'],
  'adblueIntro':'AdBlue is injected into the exhaust system of SCR-equipped diesel vehicles to help reduce nitrogen-oxide emissions. It has a separate tank.','adblueHeads':['Item','Specification'],'adblueRows':[('Quality standard','ISO 22241-1, part of the ISO 22241 series'),('Solution designation','AUS 32, also DEF'),('High-purity synthetic urea','32.5% by mass'),('Demineralised water','67.5% by mass')],'adblueNote':'This is composition by mass, not a volume ratio in litres.',
  'refill':['Park on level ground and switch off the engine and ignition.','Use ready-to-use AdBlue meeting ISO 22241-1.','Observe the minimum and maximum refill quantity shown on the display or in the manual.','When using a suitable filling nozzle, stop after its first automatic shut-off.'],'refillWarning':'Do not dilute AdBlue with water, add additives, or ever pour it into the fuel tank. If fluids are mixed up, do not start the engine; contact a workshop.',
  'empty':['The vehicle warns of a low supply and displays the remaining range.','A running engine does not automatically switch off solely because AdBlue is exhausted. Once the displayed range reaches zero, however, the engine cannot be restarted after it is switched off. Do not postpone topping up until the final kilometres.'],'recognitionTitle':'Topped up AdBlue but the message remains?','recognition':['Recognition can take some time. On some vehicles, first switch on the ignition only and wait approximately 30 seconds before starting the engine. The procedure in the exact vehicle manual governs.','Once the displayed range has expired and a no-start restriction has been activated, topping up AdBlue alone is not sufficient on some models. Starting must be enabled again by diagnostic equipment under the manufacturer procedure; some versions also require diagnostic adaptation of the level. If the restriction remains or an SCR/AdBlue fault is displayed, diagnosis and repair of the cause are required. Adding fluid alone does not repair a system fault.']},
 'de':{
  'intro':'DPF- und GPF/OPF-Filter halten Partikel zurück. AdBlue hilft dem SCR-System, Stickoxidemissionen zu senken. Jedes System hat eine andere Funktion und erfordert bei einer Warnleuchte ein anderes Vorgehen.',
  'titles':['DPF und GPF/OPF – was bedeutet die Warnleuchte?','Wie lässt sich die Regeneration während der Fahrt unterstützen?','Leuchte bleibt an oder weitere Warnungen erscheinen','DPF-Lebensdauer – Erfahrungen von J&S SERVIS','AdBlue – Funktion, Norm und Zusammensetzung','AdBlue richtig nachfüllen','Was geschieht, wenn AdBlue nicht nachgefüllt wird?'],
  'filters':['DPF ist der Partikelfilter für Dieselmotoren. GPF/OPF bezeichnet den Partikelfilter für Benzinmotoren.','Im normalen Betrieb wird der gesammelte Ruß während der Regeneration fortlaufend verbrannt. Häufige Kurzstrecken können den Abschluss verhindern. Die Filterwarnleuchte kann daher zu einer Regenerationsfahrt auffordern.'],
  'regenIntro':['Der Motor muss warm sein. Das genaue Verfahren immer in der Fahrzeuganleitung prüfen; Geschwindigkeit, Drehzahl und Fahrdauer unterscheiden sich je nach Motor.'],'regenTitle':'Beispiele aus Anleitungen ausgewählter Audi-Fahrzeuge','regenHeads':['Filter','Empfohlenes Verfahren'],'regenRows':[('Diesel – DPF','Mindestens 60 km/h bei wenigstens 2.000 U/min fahren. Die Regeneration kann etwa 20–40 Minuten dauern. Das Erlöschen der Leuchte zeigt den erfolgreichen Abschluss an.'),('Benzin – GPF/OPF','Auf mindestens 80 km/h beschleunigen, anschließend das Fahrpedal einige Sekunden vollständig loslassen und das Fahrzeug mit eingelegtem Gang verzögern lassen. Nach Anleitung wiederholen, bis die Leuchte erlischt.')],'regenNote':'Geschwindigkeitsbegrenzungen beachten und die Fahrt an Verkehr und Wetter anpassen. Diese Beispiele sind keine allgemeine Anleitung für alle Fahrzeuge des Volkswagen Konzerns.','heat':'Während der Regeneration können Leerlaufdrehzahl und Geruch zunehmen oder der Lüfter nach dem Abstellen weiterlaufen. Wegen der hohen Abgastemperatur nicht über trockenem Gras oder anderem brennbaren Material parken.',
  'warnings':['Erlischt die Leuchte nach einer Fahrt gemäß Anleitung nicht oder kehrt sie wiederholt zurück, ist eine Diagnose erforderlich.','Leuchten weitere Warnungen, blinkt die Vorglüh- oder Motorkontrollleuchte oder verliert das Fahrzeug Leistung, keine weitere Regenerationsfahrt versuchen. Werkstatt oder Pannenhilfe kontaktieren.','Bei einer roten Warnung die Fahrzeuganweisung befolgen und sicher anhalten.'],
  'life':['Nach unserer Werkstatterfahrung befindet sich der DPF mancher Dieselfahrzeuge um 250.000 km an der Lebensdauergrenze. Dies ist kein festes Wechselintervall.','Ruß verbrennt bei der Regeneration, nicht brennbare Asche bleibt jedoch im Filter. Der tatsächliche Zustand, die Diagnose und das Herstellervorgehen entscheiden über fachgerechte Reinigung oder Ersatz. Diese Laufleistung darf nicht automatisch auf Benzin-GPF/OPF übertragen werden.'],
  'adblueIntro':'AdBlue wird bei Dieselfahrzeugen mit SCR in die Abgasanlage eingespritzt und hilft, Stickoxidemissionen zu senken. Es besitzt einen eigenen Tank.','adblueHeads':['Angabe','Spezifikation'],'adblueRows':[('Qualitätsnorm','ISO 22241-1, Teil der Normenreihe ISO 22241'),('Lösungsbezeichnung','AUS 32, auch DEF'),('Hochreiner synthetischer Harnstoff','32,5 Masse-%'),('Demineralisiertes Wasser','67,5 Masse-%')],'adblueNote':'Dies ist die Zusammensetzung nach Masse und kein Volumenverhältnis in Litern.',
  'refill':['Auf ebenem Untergrund parken und Motor sowie Zündung ausschalten.','Gebrauchsfertiges AdBlue nach ISO 22241-1 verwenden.','Die im Display oder in der Anleitung angegebene minimale und maximale Nachfüllmenge beachten.','Bei einer geeigneten Zapfpistole das Befüllen nach dem ersten automatischen Abschalten beenden.'],'refillWarning':'AdBlue nicht mit Wasser verdünnen, keine Zusätze beigeben und niemals in den Kraftstofftank füllen. Bei einer Verwechslung den Motor nicht starten und eine Werkstatt kontaktieren.',
  'empty':['Das Fahrzeug warnt vor niedrigem Vorrat und zeigt die verbleibende Reichweite an.','Ein laufender Motor schaltet sich nicht allein wegen aufgebrauchtem AdBlue automatisch ab. Nach Erreichen von null Restreichweite lässt er sich nach dem Abstellen jedoch nicht erneut starten. Das Nachfüllen nicht bis zu den letzten Kilometern aufschieben.'],'recognitionTitle':'AdBlue nachgefüllt, aber die Meldung bleibt?','recognition':['Die Erkennung kann etwas dauern. Bei manchen Fahrzeugen zunächst nur die Zündung einschalten und etwa 30 Sekunden warten, bevor der Motor gestartet wird. Maßgeblich ist die Anleitung des konkreten Fahrzeugs.','Ist die angezeigte Restreichweite abgelaufen und die Startsperre aktiviert, reicht das Nachfüllen von AdBlue bei manchen Modellen nicht aus. Die Startmöglichkeit muss nach Herstellervorgabe mit Diagnosegerät wieder freigeschaltet werden; einige Ausführungen benötigen zusätzlich eine diagnostische Füllstandsanpassung. Bleibt die Sperre bestehen oder wird eine SCR-/AdBlue-Störung angezeigt, sind Diagnose und Ursachenbeseitigung erforderlich. Bloßes Nachfüllen beseitigt keinen Systemfehler.']}
}

def emissions_content(lang):
 u=EMISSIONS_UI[lang]
 def paragraphs(items):return "".join(f'<p>{esc(x)}</p>' for x in items)
 def table(heads,rows,extra):
  out=f'<table class="emissions-table {extra}"><thead><tr>'+"".join(f'<th scope="col">{esc(x)}</th>' for x in heads)+'</tr></thead><tbody>'
  for row in rows:out+='<tr>'+"".join(f'<td data-label="{esc(label)}">{esc(value)}</td>' for label,value in zip(heads,row))+'</tr>'
  return out+'</tbody></table>'
 def detail(title,body):return f'<details class="emissions-section"><summary><span>{esc(title)}</span><span class="wl-group-arrow" aria-hidden="true"></span></summary><div class="emissions-section-body">{body}</div></details>'
 regen=paragraphs(u["regenIntro"])+f'<h3>{esc(u["regenTitle"])}</h3>'+table(u["regenHeads"],u["regenRows"],"emissions-regen-table")+f'<p class="emissions-note">{esc(u["regenNote"])}</p><aside class="emissions-heat" role="note">{esc(u["heat"])}</aside>'
 warnings='<ul class="emissions-points">'+"".join(f'<li>{esc(x)}</li>' for x in u["warnings"])+'</ul>'
 adblue=f'<p>{esc(u["adblueIntro"])}</p>'+table(u["adblueHeads"],u["adblueRows"],"emissions-adblue-table")+f'<p class="emissions-note">{esc(u["adblueNote"])}</p>'
 refill='<ol class="emissions-steps">'+"".join(f'<li>{esc(x)}</li>' for x in u["refill"])+'</ol>'+f'<aside class="emissions-fluid-warning" role="alert">{esc(u["refillWarning"])}</aside>'
 empty=paragraphs(u["empty"])+f'<h3>{esc(u["recognitionTitle"])}</h3><p>{esc(u["recognition"][0])}</p><aside class="emissions-start-lock" role="note">{esc(u["recognition"][1])}</aside>'
 bodies=[paragraphs(u["filters"]),regen,warnings,paragraphs(u["life"]),adblue,refill,empty]
 return f'<div class="emissions-guide"><p class="emissions-intro">{esc(u["intro"])}</p><div class="emissions-accordion">'+"".join(detail(a,b) for a,b in zip(u["titles"],bodies))+'</div></div>'

BRAKE_FLUID_UI={
 'cs':{
  'intro':'Brzdová kapalina přenáší hydraulický tlak k brzdám. Její správná specifikace, hladina a stav jsou zásadní pro bezpečné brzdění. V J&S SERVIS při běžném servisu kontrolujeme hladinu a měříme bod varu brzdové kapaliny.',
  'titles':['Jaká kapalina patří do vozů Volkswagen Group?','Po jaké době se kapalina mění?','Proč měříme bod varu?','Proč hladina postupně klesá?','Opakované dolévání vyžaduje kontrolu'],
  'spec':['U řady vozů Volkswagen, Audi, Škoda, SEAT a CUPRA je předepsána brzdová kapalina podle normy VW 501 14, se sníženou viskozitou za nízkých teplot.','Samotný nápis „DOT 4“ na obalu nestačí k potvrzení vhodnosti pro každý vůz. Rozhoduje přesná specifikace předepsaná výrobcem. Nízká viskozita je důležitá také pro rychlou činnost systémů ABS a ESC při nízkých teplotách.'],
  'productTitle':'Příklady originálních objednacích čísel','productHeads':['Objednací číslo','Velikost balení'],'productRows':[('B 000 750 M1','250 ml'),('B 000 750 M2','500 ml'),('B 000 750 M3','1 litr')],'productNote':'Jde o velikosti balení, nikoli o předepsané množství pro výměnu. Použitelnost a případné aktuální náhrady ověřujeme v katalogu podle konkrétního vozidla.',
  'intervalIntro':'Rozhoduje časový servisní plán konkrétního vozu. Malý nájezd kilometrů není důvodem k odkládání výměny.','intervalHeads':['Servisní režim','Interval'],'intervalRows':[('Běžný interval u řady současných vozů','Každé 2 roky'),('Vybrané starší modely','První výměna po 3 letech, potom každé 2 roky'),('Například Škoda Enyaq a Volkswagen ID.','Každé 2 roky podle příslušného plánu')],'intervalNote':'První tříletý interval nelze automaticky vztáhnout na všechny nové vozy. Brzdovou kapalinu potřebují pravidelně měnit také elektromobily.',
  'boiling':['Brzdová kapalina postupně přijímá vlhkost, která snižuje její bod varu. Při intenzivním brzdění potom může začít vařit dříve.','Vzniklé stlačitelné parní bubliny mohou způsobit měkký pedál, prodloužení jeho chodu a výrazný pokles brzdného účinku až jeho selhání.','Naměřený bod varu kolem 180 °C a nižší znamená sníženou tepelnou rezervu. Z preventivních důvodů doporučujeme výměnu kapaliny. Riziko se projeví zejména při velkém tepelném zatížení, například při dlouhém brzdění ve sjezdu. Nejde o teplotu, při které brzdy automaticky přestanou fungovat.','Výsledek měření posuzujeme podle předepsané kapaliny. Ani dobrý výsledek nenahrazuje výměnu v termínu stanoveném výrobcem.'],
  'level':['Mírný pokles může souviset s opotřebením brzdových destiček. Písty se postupně vysouvají a v brzdových třmenech zůstává větší objem kapaliny. V nádržce proto hladina klesá, aniž by kapalina musela unikat.','Ani jednorázová potřeba doplnění však sama nepotvrzuje opotřebené destičky. Je nutné zkontrolovat jejich stav i těsnost soustavy. Kapalinu nedoplňujeme automaticky k MAX bez zjištění příčiny poklesu.'],
  'repeat':['Brzdová kapalina se běžným provozem nespotřebovává. Opakovaný nebo rychlý pokles hladiny může signalizovat netěsnost či jinou závadu. Pouhé dolévání problém neřeší.','V J&S SERVIS zkontrolujeme příčinu úbytku, stav brzd a těsnost příslušné hydraulické soustavy.'],
  'safetyTitle':'Bezpečnostní upozornění','safety':'Při červeném upozornění na nízkou hladinu brzdové kapaliny nebo při náhlém zhoršení brzdného účinku nepokračujte v jízdě a zajistěte odbornou pomoc.'},
 'en':{
  'intro':'Brake fluid transmits hydraulic pressure to the brakes. The correct specification, level and condition are essential for safe braking. During routine service, J&S SERVIS checks the level and measures the brake fluid boiling point.',
  'titles':['Which fluid belongs in Volkswagen Group vehicles?','When should the fluid be changed?','Why do we measure the boiling point?','Why does the level gradually fall?','Repeated topping up requires inspection'],
  'spec':['Many Volkswagen, Audi, Škoda, SEAT and CUPRA vehicles specify low-viscosity brake fluid meeting VW 501 14.','A “DOT 4” label alone does not confirm suitability for every vehicle. The manufacturer’s exact specification governs. Low viscosity also supports rapid ABS and ESC operation at low temperatures.'],
  'productTitle':'Examples of genuine part numbers','productHeads':['Part number','Pack size'],'productRows':[('B 000 750 M1','250 ml'),('B 000 750 M2','500 ml'),('B 000 750 M3','1 litre')],'productNote':'These are pack sizes, not the prescribed quantity for a fluid change. We verify suitability and any current superseding number in the catalogue for the exact vehicle.',
  'intervalIntro':'The time-based service schedule for the exact vehicle governs. Low mileage is not a reason to postpone the change.','intervalHeads':['Service regime','Interval'],'intervalRows':[('Common interval for many current vehicles','Every 2 years'),('Selected older models','First change after 3 years, then every 2 years'),('For example Škoda Enyaq and Volkswagen ID.','Every 2 years under the applicable schedule')],'intervalNote':'The initial three-year interval must not be applied automatically to every new vehicle. Electric vehicles also require regular brake-fluid changes.',
  'boiling':['Brake fluid gradually absorbs moisture, which lowers its boiling point. It can then boil sooner during intensive braking.','The resulting compressible vapour bubbles can cause a soft pedal, increased pedal travel and a major reduction or loss of braking effect.','A measured boiling point around 180 °C or lower means reduced thermal reserve. We recommend preventive fluid replacement. The risk is most relevant under high heat load, such as prolonged braking on a descent. This is not a temperature at which the brakes automatically stop working.','We assess the result against the specified fluid. Even a good result does not replace a change due under the manufacturer’s schedule.'],
  'level':['A slight fall can be associated with brake-pad wear. The pistons extend progressively, leaving more fluid in the calipers, so the reservoir level can fall without a leak.','A single need to top up does not by itself prove worn pads. Pad condition and system tightness must be checked. We do not automatically fill to MAX without finding the cause of the lower level.'],
  'repeat':['Brake fluid is not consumed in normal operation. A repeated or rapid fall can indicate a leak or another fault. Topping up alone does not solve the problem.','J&S SERVIS checks the cause of the loss, brake condition and tightness of the relevant hydraulic system.'],
  'safetyTitle':'Safety warning','safety':'With a red low brake-fluid warning or a sudden deterioration in braking effect, do not continue driving; arrange qualified assistance.'},
 'de':{
  'intro':'Bremsflüssigkeit überträgt den hydraulischen Druck zu den Bremsen. Richtige Spezifikation, Füllstand und Zustand sind für sicheres Bremsen entscheidend. Beim regulären Service prüft J&S SERVIS den Füllstand und misst den Siedepunkt der Bremsflüssigkeit.',
  'titles':['Welche Flüssigkeit gehört in Fahrzeuge des Volkswagen Konzerns?','Wann muss die Flüssigkeit gewechselt werden?','Warum messen wir den Siedepunkt?','Warum sinkt der Füllstand allmählich?','Wiederholtes Nachfüllen erfordert eine Prüfung'],
  'spec':['Für viele Fahrzeuge von Volkswagen, Audi, Škoda, SEAT und CUPRA ist niedrigviskose Bremsflüssigkeit nach VW 501 14 vorgeschrieben.','Die Aufschrift „DOT 4“ allein bestätigt nicht die Eignung für jedes Fahrzeug. Maßgeblich ist die genaue Herstellerspezifikation. Niedrige Viskosität unterstützt auch die schnelle Funktion von ABS und ESC bei tiefen Temperaturen.'],
  'productTitle':'Beispiele für Original-Teilenummern','productHeads':['Teilenummer','Gebindegröße'],'productRows':[('B 000 750 M1','250 ml'),('B 000 750 M2','500 ml'),('B 000 750 M3','1 Liter')],'productNote':'Dies sind Gebindegrößen und keine vorgeschriebene Wechselmenge. Eignung und aktuelle Ersetzungen prüfen wir anhand des konkreten Fahrzeugs im Katalog.',
  'intervalIntro':'Maßgeblich ist der zeitabhängige Serviceplan des konkreten Fahrzeugs. Eine geringe Laufleistung ist kein Grund, den Wechsel aufzuschieben.','intervalHeads':['Serviceregelung','Intervall'],'intervalRows':[('Übliches Intervall bei vielen aktuellen Fahrzeugen','Alle 2 Jahre'),('Ausgewählte ältere Modelle','Erster Wechsel nach 3 Jahren, danach alle 2 Jahre'),('Zum Beispiel Škoda Enyaq und Volkswagen ID.','Alle 2 Jahre nach dem zutreffenden Plan')],'intervalNote':'Das erste Dreijahresintervall darf nicht automatisch auf alle Neufahrzeuge übertragen werden. Auch Elektrofahrzeuge benötigen regelmäßige Bremsflüssigkeitswechsel.',
  'boiling':['Bremsflüssigkeit nimmt allmählich Feuchtigkeit auf, wodurch ihr Siedepunkt sinkt. Bei starker Bremsbeanspruchung kann sie dadurch früher sieden.','Die entstehenden kompressiblen Dampfblasen können ein weiches Pedal, einen längeren Pedalweg und eine deutliche Verringerung bis zum Ausfall der Bremswirkung verursachen.','Ein gemessener Siedepunkt um 180 °C oder darunter bedeutet eine verringerte thermische Reserve. Vorbeugend empfehlen wir den Flüssigkeitswechsel. Das Risiko zeigt sich besonders bei hoher Wärmebelastung, etwa langem Bremsen im Gefälle. Es ist keine Temperatur, bei der die Bremsen automatisch ausfallen.','Das Messergebnis wird anhand der vorgeschriebenen Flüssigkeit beurteilt. Auch ein guter Wert ersetzt den termingerechten Wechsel nach Herstellervorgabe nicht.'],
  'level':['Ein leichter Rückgang kann mit dem Verschleiß der Bremsbeläge zusammenhängen. Die Kolben fahren schrittweise weiter aus und in den Bremssätteln verbleibt mehr Flüssigkeit. Dadurch kann der Behälterstand auch ohne Leck sinken.','Ein einmaliger Nachfüllbedarf beweist jedoch nicht von selbst verschlissene Beläge. Belagzustand und Dichtheit der Anlage müssen geprüft werden. Ohne Klärung der Ursache füllen wir nicht automatisch bis MAX auf.'],
  'repeat':['Bremsflüssigkeit wird im normalen Betrieb nicht verbraucht. Ein wiederholter oder schneller Abfall kann auf eine Undichtigkeit oder einen anderen Fehler hinweisen. Bloßes Nachfüllen löst das Problem nicht.','J&S SERVIS prüft die Ursache des Verlusts, den Bremsenzustand und die Dichtheit des betreffenden Hydrauliksystems.'],
  'safetyTitle':'Sicherheitshinweis','safety':'Bei einer roten Warnung wegen zu niedrigen Bremsflüssigkeitsstands oder einer plötzlichen Verschlechterung der Bremswirkung nicht weiterfahren und Fachhilfe anfordern.'}
}


def brake_fluid_content(lang):
 u=BRAKE_FLUID_UI[lang]
 def paragraphs(items):return "".join(f'<p>{esc(x)}</p>' for x in items)
 def table(heads,rows,extra):
  out=f'<table class="brake-fluid-table {extra}"><thead><tr>'+"".join(f'<th scope="col">{esc(x)}</th>' for x in heads)+'</tr></thead><tbody>'
  for row in rows:out+='<tr>'+"".join(f'<td data-label="{esc(label)}">{esc(value)}</td>' for label,value in zip(heads,row))+'</tr>'
  return out+'</tbody></table>'
 def detail(title,body):return f'<details class="brake-fluid-section"><summary><span>{esc(title)}</span><span class="wl-group-arrow" aria-hidden="true"></span></summary><div class="brake-fluid-section-body">{body}</div></details>'
 specification=paragraphs(u["spec"])+f'<h3>{esc(u["productTitle"])}</h3>'+table(u["productHeads"],u["productRows"],"brake-fluid-products")+f'<p class="brake-fluid-note">{esc(u["productNote"])}</p>'
 intervals=f'<p>{esc(u["intervalIntro"])}</p>'+table(u["intervalHeads"],u["intervalRows"],"brake-fluid-intervals")+f'<p class="brake-fluid-note">{esc(u["intervalNote"])}</p>'
 bodies=[specification,intervals,paragraphs(u["boiling"]),paragraphs(u["level"]),paragraphs(u["repeat"])]
 accordion="".join(detail(title,body) for title,body in zip(u["titles"],bodies))
 safety=f'<aside class="brake-fluid-safety" role="alert"><h2>{esc(u["safetyTitle"])}</h2><p>{esc(u["safety"])}</p></aside>'
 return f'<div class="brake-fluid-guide"><p class="brake-fluid-intro">{esc(u["intro"])}</p><div class="brake-fluid-accordion">{accordion}</div>{safety}</div>'

SERVICE_UI={
 'cs':{
  'intro':'Servisní interval určuje konkrétní vozidlo, jeho výbava, provozní podmínky a aktuální servisní nastavení. Termín olejového servisu a servisní prohlídky posuzujte odděleně.','recommend':'J&S SERVIS doporučuje výměnu motorového oleje a filtru nejpozději po 1 roce nebo 15 000 km – podle toho, co nastane dříve. Předepisuje-li výrobce kratší interval, platí kratší.','titles':['Pevný interval a LongLife','Co znamenají kódy QI a QG','Kde zjistím svůj servisní interval','Možnosti přenastavení intervalu','Servis elektromobilů a hybridů','Výměna oleje versus servisní prohlídka'],'fixedHeads':['Režim','Jak se termín určuje','Důležité'],'fixedRows':[('Pevný interval','Předem stanovený čas a počet kilometrů. Termín nastane podle hodnoty, která se naplní dříve.','Používá se pevně nastavený servisní ukazatel a odpovídající olejový režim.'),('LongLife / flexibilní','Vozidlo vypočítává termín olejového servisu podle provozních dat; současně platí nejzazší mez výrobce.','LongLife olej sám režim nezapne ani automaticky neprodlouží interval.')],
  'qiIntro':'Kódy QI jsou PR kódy servisního ukazatele. Následující hodnoty jsou významy kódů, nikoli doporučení J&S SERVIS:','qiHeads':['Kód','Servisní ukazatel'],'qiRows':[('QI0','Bez servisního ukazatele.'),('QI1','Pevný: 5 000 km nebo 1 rok.'),('QI2','Pevný: 7 500 km nebo 1 rok.'),('QI3','Pevný: 10 000 km nebo 1 rok.'),('QI4','Pevný: 15 000 km nebo 1 rok.'),('QI6','Flexibilní servis; konkrétní termín vypočítá vozidlo, nejpozději podle mezí výrobce pro dané provedení.')],
  'qgIntro':'Kódy QG se vyskytují hlavně ve starší dokumentaci. Jejich použití se podle výrobního období změnilo, proto je nelze bez kontextu použít jako dnešní servisní plán:','qgHeads':['Kód','Význam ve starší dokumentaci'],'qgRows':[('QG0','Bez prodloužených servisních intervalů.'),('QG1','S prodlouženými servisními intervaly (LongLife).'),('QG2','Bez možnosti aktivace prodlouženého intervalu.')],'qgNote':'U novějších vozidel se servisní režim rozlišuje kódy QI; QG může popisovat jinou výbavu, například přítomnost snímače oleje. Rozhoduje datový štítek, VIN, dokumentace a skutečné nastavení vozidla.',
  'where':[('Datový štítek','PR kódy mohou být na datovém štítku vozidla nebo v servisní dokumentaci. Štítek nemusí být u všech vozidel ve stejné podobě ani na stejném místě.'),('VIN a katalog výrobce','Podle celého VIN lze ověřit výrobní provedení a odpovídající servisní plán.'),('Aktuální nastavení vozidla','Ukazatel v přístrojovém panelu nebo infotainmentu zobrazuje aktuálně nastavený termín. Samotný údaj neprokazuje, že předchozí přenastavení bylo správné.')],
  'recode':['Nejprve ověřit, zda výrobce pro konkrétní vozidlo připouští pevný i flexibilní režim.','Použít olej se schválením odpovídajícím zvolenému režimu a motoru.','Přenastavit servisní ukazatel diagnostikou podle postupu výrobce; pouhé vynulování nemusí změnit režim.','Zapsat provedenou změnu a nový termín do servisní historie.','Interval nezkracovat ani neprodlužovat v rozporu s kratší závaznou podmínkou výrobce.'],
  'evHeads':['Modelová skupina','Motorový olej','Servis a výjimky'],'evRows':[('Čisté elektromobily MEB: Volkswagen ID., Škoda Enyaq/Elroq, CUPRA Born/Tavascan, Audi Q4 e-tron','Nemají spalovací motor, proto nemají výměnu motorového oleje.','Servisní prohlídky, brzdová kapalina, filtry, brzdy, pneumatiky a další úkony mají vlastní termíny podle modelu, trhu a provozu.'),('Další čisté elektromobily Audi e-tron / Q8 e-tron a e-tron GT','Nemají servis motorového oleje spalovacího motoru.','Konstrukce se liší od MEB; používejte servisní plán přesného modelu. Převodové náplně a chladicí okruhy nejsou motorový olej.'),('Plug-in hybridy: GTE, eHybrid, TFSI e, iV a e-HYBRID','Mají spalovací motor; jeho olej a filtr se mění podle předepsaného režimu.','Současně mají samostatné úkony vysokonapěťové soustavy. Častý studený provoz spalovacího motoru může odůvodnit kratší doporučený interval.'),('Mild-hybridy a běžné hybridy se spalovacím motorem','Výměna motorového oleje zůstává nutná.','Elektrifikace sama neruší olejový servis. Rozhoduje konkrétní motor, VIN a servisní plán.')],
  'evNote':'Modelový název ani elektrický pohon neurčuje univerzální interval. Výjimky podle výrobního období, trhu, pohonu, výbavy a svolávacích či servisních opatření ověřte podle VIN.',
  'difference':[('Olejový servis','Výměna motorového oleje a olejového filtru; má vlastní termín podle režimu, motoru a provozu.'),('Servisní prohlídka','Kontroly vozidla a další předepsané úkony. Může mít jiný termín než olejový servis.'),('Samostatné úkony','Brzdová kapalina, filtry, svíčky, převodovky, pohon všech kol a další položky mohou mít vlastní časové nebo kilometrové podmínky.')],'differenceNote':'Provedení jednoho úkonu automaticky neznamená splnění ostatních. Po servisu musí být správně zaznamenán a nastaven každý příslušný termín.'},
 'en':{
  'intro':'The service interval depends on the exact vehicle, equipment, operating conditions and current service configuration. Treat the oil service and inspection dates separately.','recommend':'J&S SERVIS recommends replacing the engine oil and filter no later than after 1 year or 15,000 km, whichever comes first. If the manufacturer specifies a shorter interval, the shorter interval applies.','titles':['Fixed interval and LongLife','What QI and QG codes mean','Where to find my service interval','Options for changing the interval setting','Servicing electric and hybrid vehicles','Oil change versus service inspection'],'fixedHeads':['Regime','How the date is determined','Important'],'fixedRows':[('Fixed interval','A predetermined time and mileage; whichever limit is reached first.','Uses a fixed service display and the corresponding oil regime.'),('LongLife / flexible','The vehicle calculates the oil-service date from operating data, subject to the manufacturer’s maximum limit.','LongLife oil alone neither activates the regime nor automatically extends the interval.')],
  'qiIntro':'QI codes are PR codes for the service display. These are code meanings, not J&S SERVIS recommendations:','qiHeads':['Code','Service display'],'qiRows':[('QI0','Without a service display.'),('QI1','Fixed: 5,000 km or 1 year.'),('QI2','Fixed: 7,500 km or 1 year.'),('QI3','Fixed: 10,000 km or 1 year.'),('QI4','Fixed: 15,000 km or 1 year.'),('QI6','Flexible service; the vehicle calculates the date, no later than the manufacturer limit for the exact version.')],
  'qgIntro':'QG codes mainly occur in older documentation. Their use changed by production period, so they cannot establish a current service plan without context:','qgHeads':['Code','Meaning in older documentation'],'qgRows':[('QG0','Without extended service intervals.'),('QG1','With extended service intervals (LongLife).'),('QG2','Without the option to activate an extended interval.')],'qgNote':'Newer vehicles distinguish the service regime with QI codes; QG may describe other equipment such as an oil sensor. Use the data sticker, VIN, documentation and actual vehicle configuration.',
  'where':[('Vehicle data sticker','PR codes may appear on the vehicle data sticker or in service documentation. Form and location are not identical on every vehicle.'),('VIN and manufacturer catalogue','The complete VIN can identify the production version and matching service plan.'),('Current vehicle setting','The instrument panel or infotainment shows the currently configured due date. It does not prove that a previous recoding was correct.')],
  'recode':['First verify that the manufacturer permits both fixed and flexible regimes for the exact vehicle.','Use oil approved for the selected regime and engine.','Recode the service display diagnostically under the manufacturer procedure; merely resetting it need not change the regime.','Record the change and new due date in the service history.','Never override a shorter binding manufacturer condition.'],
  'evHeads':['Model group','Engine oil','Service and exceptions'],'evRows':[('MEB battery-electric vehicles: Volkswagen ID., Škoda Enyaq/Elroq, CUPRA Born/Tavascan, Audi Q4 e-tron','No combustion engine and therefore no engine-oil change.','Inspections, brake fluid, filters, brakes, tyres and other tasks have their own dates by model, market and operation.'),('Other Audi battery-electric vehicles: e-tron / Q8 e-tron and e-tron GT','No combustion-engine oil service.','Design differs from MEB; use the exact model plan. Gear fluids and cooling circuits are not engine oil.'),('Plug-in hybrids: GTE, eHybrid, TFSI e, iV and e-HYBRID','Have a combustion engine; its oil and filter follow the prescribed regime.','High-voltage tasks are separate. Frequent cold combustion-engine use can justify the shorter recommended interval.'),('Mild hybrids and other hybrids with a combustion engine','Engine-oil changes remain necessary.','Electrification does not cancel oil service. The exact engine, VIN and service plan govern.')],
  'evNote':'A model name or electric drive does not define a universal interval. Verify exceptions for production period, market, powertrain, equipment and service actions by VIN.',
  'difference':[('Oil service','Engine-oil and oil-filter replacement, with its own date based on regime, engine and operation.'),('Service inspection','Vehicle checks and other prescribed work. Its date can differ from the oil service.'),('Separate operations','Brake fluid, filters, spark plugs, transmissions, all-wheel drive and other items can have their own time or mileage conditions.')],'differenceNote':'Completing one operation does not automatically complete the others. Each applicable date must be recorded and configured correctly after service.'},
 'de':{
  'intro':'Das Serviceintervall hängt vom konkreten Fahrzeug, der Ausstattung, den Betriebsbedingungen und der aktuellen Serviceeinstellung ab. Ölservice und Inspektion sind getrennt zu beurteilen.','recommend':'J&S SERVIS empfiehlt, Motoröl und Ölfilter spätestens nach 1 Jahr oder 15.000 km zu wechseln – je nachdem, was zuerst eintritt. Schreibt der Hersteller ein kürzeres Intervall vor, gilt das kürzere.','titles':['Festes Intervall und LongLife','Bedeutung der QI- und QG-Codes','Wo finde ich mein Serviceintervall?','Möglichkeiten zur Intervallumstellung','Service von Elektro- und Hybridfahrzeugen','Ölwechsel versus Serviceinspektion'],'fixedHeads':['Regime','Terminbestimmung','Wichtig'],'fixedRows':[('Festes Intervall','Vorgegebene Zeit und Laufleistung; maßgeblich ist die zuerst erreichte Grenze.','Feste Serviceanzeige und dazu passendes Ölregime.'),('LongLife / flexibel','Das Fahrzeug berechnet den Ölservicetermin aus Betriebsdaten; zugleich gilt die Herstellerhöchstgrenze.','LongLife-Öl allein aktiviert das Regime nicht und verlängert das Intervall nicht automatisch.')],
  'qiIntro':'QI-Codes sind PR-Codes der Serviceanzeige. Die Werte erklären die Codes und sind keine Empfehlung von J&S SERVIS:','qiHeads':['Code','Serviceanzeige'],'qiRows':[('QI0','Ohne Serviceanzeige.'),('QI1','Fest: 5.000 km oder 1 Jahr.'),('QI2','Fest: 7.500 km oder 1 Jahr.'),('QI3','Fest: 10.000 km oder 1 Jahr.'),('QI4','Fest: 15.000 km oder 1 Jahr.'),('QI6','Flexibler Service; das Fahrzeug berechnet den Termin, spätestens nach der Herstellergrenze der konkreten Ausführung.')],
  'qgIntro':'QG-Codes kommen vor allem in älteren Unterlagen vor. Ihre Verwendung änderte sich mit dem Produktionszeitraum; ohne Kontext bestimmen sie keinen heutigen Serviceplan:','qgHeads':['Code','Bedeutung in älteren Unterlagen'],'qgRows':[('QG0','Ohne verlängerte Serviceintervalle.'),('QG1','Mit verlängerten Serviceintervallen (LongLife).'),('QG2','Ohne Möglichkeit zur Aktivierung eines verlängerten Intervalls.')],'qgNote':'Bei neueren Fahrzeugen kennzeichnen QI-Codes das Serviceregime; QG kann andere Ausstattung wie einen Ölsensor beschreiben. Maßgeblich sind Datenträger, VIN, Unterlagen und tatsächliche Fahrzeugeinstellung.',
  'where':[('Fahrzeugdatenträger','PR-Codes können auf dem Fahrzeugdatenträger oder in den Serviceunterlagen stehen. Form und Einbauort sind nicht bei allen Fahrzeugen gleich.'),('VIN und Herstellerkatalog','Mit der vollständigen VIN lassen sich Produktionsausführung und passender Serviceplan prüfen.'),('Aktuelle Fahrzeugeinstellung','Kombiinstrument oder Infotainment zeigt den aktuell eingestellten Termin. Dies beweist nicht, dass eine frühere Umstellung korrekt war.')],
  'recode':['Zuerst prüfen, ob der Hersteller für das konkrete Fahrzeug festes und flexibles Regime zulässt.','Öl mit Freigabe für gewähltes Regime und Motor verwenden.','Serviceanzeige nach Herstellervorgabe diagnostisch umcodieren; bloßes Zurücksetzen ändert das Regime nicht zwingend.','Änderung und neuen Termin in der Servicehistorie dokumentieren.','Eine kürzere verbindliche Herstellervorgabe nicht überschreiten.'],
  'evHeads':['Modellgruppe','Motoröl','Service und Ausnahmen'],'evRows':[('MEB-Elektrofahrzeuge: Volkswagen ID., Škoda Enyaq/Elroq, CUPRA Born/Tavascan, Audi Q4 e-tron','Kein Verbrennungsmotor und daher kein Motorölwechsel.','Inspektionen, Bremsflüssigkeit, Filter, Bremsen, Reifen und weitere Arbeiten haben eigene Termine nach Modell, Markt und Betrieb.'),('Weitere Audi-Elektrofahrzeuge: e-tron / Q8 e-tron und e-tron GT','Kein Motorölservice eines Verbrennungsmotors.','Andere Konstruktion als MEB; Plan des genauen Modells verwenden. Getriebeöle und Kühlkreise sind kein Motoröl.'),('Plug-in-Hybride: GTE, eHybrid, TFSI e, iV und e-HYBRID','Verbrennungsmotor vorhanden; Öl und Filter nach vorgeschriebenem Regime.','Arbeiten am Hochvoltsystem sind getrennt. Häufiger kalter Motorbetrieb kann das kürzere empfohlene Intervall begründen.'),('Mildhybride und andere Hybride mit Verbrennungsmotor','Motorölwechsel bleibt erforderlich.','Elektrifizierung hebt den Ölservice nicht auf. Konkreter Motor, VIN und Serviceplan entscheiden.')],
  'evNote':'Modellname oder Elektroantrieb bestimmt kein universelles Intervall. Ausnahmen nach Produktionszeitraum, Markt, Antrieb, Ausstattung und Serviceaktionen anhand der VIN prüfen.',
  'difference':[('Ölservice','Wechsel von Motoröl und Ölfilter mit eigenem Termin nach Regime, Motor und Betrieb.'),('Serviceinspektion','Fahrzeugkontrollen und weitere vorgeschriebene Arbeiten. Der Termin kann vom Ölservice abweichen.'),('Separate Arbeiten','Bremsflüssigkeit, Filter, Zündkerzen, Getriebe, Allradantrieb und weitere Positionen können eigene Zeit- oder Kilometerbedingungen haben.')],'differenceNote':'Eine erledigte Arbeit erfüllt nicht automatisch die übrigen. Nach dem Service ist jeder zutreffende Termin richtig zu dokumentieren und einzustellen.'}
}


def service_content(lang):
 u=SERVICE_UI[lang]
 def table(heads,rows,extra=""):
  out=f'<table class="service-table {extra}"><thead><tr>'+"".join(f'<th scope="col">{esc(x)}</th>' for x in heads)+'</tr></thead><tbody>'
  for row in rows:out+='<tr>'+"".join(f'<td data-label="{esc(label)}">{esc(value)}</td>' for label,value in zip(heads,row))+'</tr>'
  return out+'</tbody></table>'
 def detail(title,body):return f'<details class="service-section"><summary><span>{esc(title)}</span><span class="wl-group-arrow" aria-hidden="true"></span></summary><div class="service-section-body">{body}</div></details>'
 fixed=table(u["fixedHeads"],u["fixedRows"],"service-fixed-table")
 codes=f'<p>{esc(u["qiIntro"])}</p><h3>QI</h3>'+table(u["qiHeads"],u["qiRows"],"service-code-table")+f'<p>{esc(u["qgIntro"])}</p><h3>QG</h3>'+table(u["qgHeads"],u["qgRows"],"service-code-table")+f'<p class="service-note">{esc(u["qgNote"])}</p>'
 where='<dl class="service-fact-list">'+"".join(f'<div><dt>{esc(a)}</dt><dd>{esc(b)}</dd></div>' for a,b in u["where"])+'</dl>'
 recode='<ul class="service-points">'+"".join(f'<li>{esc(x)}</li>' for x in u["recode"])+'</ul>'
 ev=table(u["evHeads"],u["evRows"],"service-ev-table")+f'<p class="service-note">{esc(u["evNote"])}</p>'
 difference=table([u["fixedHeads"][0],u["fixedHeads"][2]],u["difference"],"service-difference-table")+f'<p class="service-note">{esc(u["differenceNote"])}</p>'
 bodies=[fixed,codes,where,recode,ev,difference]
 accordion="".join(detail(title,body) for title,body in zip(u["titles"],bodies))
 return f'<div class="service-guide"><p class="service-intro">{esc(u["intro"])}</p><aside class="service-recommendation" role="note">{esc(u["recommend"])}</aside><div class="service-accordion">{accordion}</div></div>'

DRIVER_TOPICS={
 'cs':{
  'page':'Rady pro řidiče','intro':'Praktické přehledy pro správnou reakci na hlášení vozidla a základní kontrolu provozních údajů. Konkrétní údaj vždy ověřte pro přesný model, modelový rok, výbavu a pohon.',
  'titles':['Identifikace mého vozu – VIN','Přihlášení a online služby vozidla','Kontrolky a výstražná hlášení','Pojistky – barvy a hodnoty','Pneumatiky – označení, tlak a štítek','Oleje – viskozita a specifikace','Chladicí kapaliny','Servis a servisní intervaly','Brzdová kapalina','Čištění výfukových plynů – DPF/GPF, AdBlue','Pohonné hmoty','Kapaliny do ostřikovačů'],
  'topics':[
   [],[],[],
   [('Typy automobilových pojistek','Před určením náhrady zjistěte konstrukční typ pojistky. Stejná barva u odlišných rodin pojistek sama nepotvrzuje shodné provedení.'),('Barevné značení a proudové hodnoty','Barvu a hodnotu v ampérech posuzujte jen v tabulce pro daný typ pojistky. Přehled neobsahuje obsazení pojistkových skříní ani přiřazení spotřebičů.'),('Jak určit odpovídající pojistku','Rozhoduje návod konkrétního vozidla, poloha ve správné pojistkové skříni, typ pojistky a předepsaná proudová hodnota.'),('Zásady správné náhrady','Vypněte příslušný spotřebič a zapalování podle návodu. Použijte pouze pojistku stejného typu a hodnoty; opakované přepálení vyžaduje diagnostiku.')],
   [('Ověření konkrétního umístění','Nejčastější místa jsou uvedena výše. Přesnou polohu vždy potvrďte v návodu pro konkrétní model, generaci a provedení vozidla.'),('Jak přečtu správné hodnoty','Nejprve porovnejte rozměr pneumatiky a stav zatížení na štítku. Hodnoty pro běžné a plné zatížení ani přední a zadní nápravu nezaměňujte.'),('Kontrola a úprava tlaku','Tlak kontrolujte na studených pneumatikách podle podmínek uvedených výrobcem. Nejdříve skutečný tlak změřte a upravte; samotné zhasnutí kontrolky není cílem.'),('Uložení nebo nastavení systému','Uložení přes infotainment, tlačítko SET nebo jiný postup lze uvést jen pro odpovídající model a systém. Po úpravě tlaku postupujte podle návodu vozidla.')],
   [('Motorové oleje a označení SAE','SAE popisuje viskozitní třídu. Neurčuje samo schválení výrobce ani vhodnost pro konkrétní motor.'),('Normy a schválení Volkswagen Group','Použijte přesné schválení uvedené pro motor a servisní režim. Shodná viskozita neprokazuje zaměnitelnost.'),('Výběr, kontrola hladiny a doplnění','Rozhoduje konkrétní motor, servisní režim a návod. Hladinu kontrolujte předepsaným postupem; nepřeplňujte.'),('Mísení a nouzové doplnění','Možnost mísení nebo nouzového doplnění musí být výslovně doložena pro danou specifikaci. Obecná podobnost názvu nestačí.'),('Převodové a další oleje','Náplně manuálních převodovek, DSG, ostatních automatů, rozvodovek, diferenciálů a spojek pohonu všech kol se posuzují odděleně podle konkrétní konstrukce.')],
   [('Označení a specifikace výrobce','Barva kapaliny není jediným kritériem. Rozhoduje specifikace předepsaná pro konkrétní vozidlo a chladicí okruh.'),('Koncentrát, hotová směs a ředění','Rozlišujte koncentrát a předmíchanou kapalinu. Poměr ředění, požadovanou vodu a ochranu proti zamrznutí přebírejte z příslušného návodu.'),('Mísitelnost a náhrady','Mísitelnost ani náhradu staršího produktu nelze odvodit jen z obchodního názvu. Musí být doložena výrobcem pro daný okruh.'),('Bezpečná kontrola a doplňování','Nikdy neotvírejte horký okruh. Při neznámé náplni, opakovaném úbytku nebo výstraze nejprve zjistěte příčinu; u hybridů a elektromobilů rozlišujte jednotlivé okruhy.')],
   [('Výběr správného servisního plánu','Je nutné určit značku, model a generaci, modelový rok, motor nebo pohon, převodovku a podle potřeby VIN, kódy agregátů a PR kódy.'),('Servisní prohlídky a olejový servis','Inspekční prohlídku, olejový servis a samostatné úkony posuzujte odděleně. Pevný a proměnlivý režim mají rozdílné podmínky.'),('Filtry, svíčky, rozvody a pomocné pohony','První a následující termíny i časové a kilometrové podmínky musí pocházet z odpovídajícího servisního plánu.'),('Převodovka, pohon všech kol, brzdy a kapaliny','Pro DSG, jiné automaty ani pohon 4×4 neexistuje jeden univerzální interval. Rozhoduje konkrétní konstrukce, servisovaný okruh, náplň a případný filtr.'),('Další údržba konkrétní výbavy','Kontrolu, doplnění, pravidelnou výměnu a výměnu podle stavu rozlišujte. Předpis výrobce a preventivní doporučení J&S SERVIS musí být uvedeny samostatně.')]
  ]},
 'en':{
  'page':'Driver advice','intro':'Practical guidance for responding to vehicle messages and checking basic operating information. Always verify a specific value for the exact model, model year, equipment and powertrain.',
  'titles':['Identifying my vehicle – VIN','Sign-in and online vehicle services','Warning lights and driver messages','Fuses – colours and ratings','Tyres – markings, pressures and placard','Oils – viscosity and specifications','Coolants','Service and maintenance intervals','Brake fluid','Exhaust-gas treatment – DPF/GPF, AdBlue','Fuels','Washer fluids'],
  'topics':[
   [],[],[],
   [('Automotive fuse types','Identify the fuse construction before selecting a replacement. A matching colour in a different fuse family does not establish the same design.'),('Colour coding and ampere ratings','Use colour and ampere rating only with the table for that fuse type. This section does not reproduce fuse-box positions or consumer assignments.'),('Selecting the correct fuse','Use the exact vehicle manual, the position in the correct fuse box, the fuse type and the specified ampere rating.'),('Safe replacement','Switch off the relevant consumer and ignition as instructed. Use only the same type and rating; repeated failure requires diagnosis.')],
   [('Verifying the exact location','Common locations are listed above. Always confirm the exact position in the manual for the specific model, generation and vehicle version.'),('Reading the correct values','Match the tyre size and load condition shown on the placard. Do not interchange normal/full-load or front/rear values.'),('Checking and adjusting pressure','Check cold tyres under the manufacturer’s stated conditions. Measure and correct the real pressure first; merely clearing a warning is not the objective.'),('Storing or setting the system','Infotainment storage, a SET button or another procedure may be assigned only to the matching model and system. Follow the vehicle manual after adjustment.')],
   [('Engine oils and SAE','SAE describes a viscosity grade. It does not by itself establish manufacturer approval or suitability for an engine.'),('Volkswagen Group approvals','Use the exact approval stated for the engine and service regime. Equal viscosity does not prove interchangeability.'),('Selection, level check and topping up','Use the exact engine, service regime and manual. Follow the prescribed level-check procedure and do not overfill.'),('Mixing and emergency top-up','Mixing or emergency top-up must be explicitly documented for the specification; a similar product name is insufficient.'),('Transmission and other oils','Manual transmissions, DSG, other automatics, transfer cases, differentials and all-wheel-drive clutches require separate assessment for the exact construction.')],
   [('Manufacturer designation and specification','Colour is not a sufficient selection criterion. Use the specification for the exact vehicle and cooling circuit.'),('Concentrate, premix and dilution','Distinguish concentrate from premix. Use the manual for dilution, water requirements and frost protection.'),('Mixing and supersession','Do not infer mixing or replacement of an older product from its trade name. Manufacturer evidence for the circuit is required.'),('Safe checking and topping up','Never open a hot circuit. With unknown coolant, repeated loss or a warning, find the cause first; distinguish separate hybrid and EV circuits.')],
   [('Selecting the correct service plan','Identify brand, model and generation, model year, engine or powertrain, transmission and, where necessary, VIN, unit codes and PR codes.'),('Inspections and oil service','Treat inspections, oil service and individual operations separately. Fixed and flexible regimes have different conditions.'),('Filters, plugs, timing and auxiliary drives','First and subsequent due dates and time/mileage conditions must come from the matching service plan.'),('Transmission, all-wheel drive, brakes and fluids','There is no universal DSG, automatic-transmission or 4×4 interval. The exact design, serviced circuit, fluid and filter determine the requirement.'),('Equipment-specific maintenance','Distinguish inspection, topping up, scheduled replacement and condition-based replacement. Manufacturer requirements and J&S SERVIS preventive advice must be separate.')]
  ]},
 'de':{
  'page':'Fahrertipps','intro':'Praktische Hinweise zur richtigen Reaktion auf Fahrzeugmeldungen und zur Kontrolle grundlegender Betriebsangaben. Konkrete Werte immer für Modell, Modelljahr, Ausstattung und Antrieb prüfen.',
  'titles':['Identifikation meines Fahrzeugs – VIN','Anmeldung und Online-Fahrzeugdienste','Kontrollleuchten und Warnmeldungen','Sicherungen – Farben und Werte','Reifen – Kennzeichnungen, Druck und Schild','Öle – Viskosität und Spezifikationen','Kühlmittel','Service und Wartungsintervalle','Bremsflüssigkeit','Abgasreinigung – DPF/GPF, AdBlue','Kraftstoffe','Scheibenwaschflüssigkeiten'],
  'topics':[
   [],[],[],
   [('Kfz-Sicherungstypen','Vor der Ersatzwahl die Bauform bestimmen. Gleiche Farben in verschiedenen Sicherungsfamilien belegen nicht dieselbe Ausführung.'),('Farbcodierung und Amperewerte','Farbe und Amperewert nur anhand der Tabelle für den jeweiligen Sicherungstyp verwenden. Sicherungskastenbelegung und Verbraucherzuordnung sind nicht Bestandteil.'),('Passende Sicherung bestimmen','Maßgeblich sind die konkrete Fahrzeuganleitung, die Position im richtigen Sicherungskasten, Bauform und vorgeschriebener Amperewert.'),('Sicher ersetzen','Betroffenen Verbraucher und Zündung nach Anleitung ausschalten. Nur gleichen Typ und Wert einsetzen; wiederholtes Auslösen erfordert Diagnose.')],
   [('Genaue Position prüfen','Häufige Stellen sind oben aufgeführt. Die genaue Position stets in der Anleitung für Modell, Generation und Fahrzeugausführung bestätigen.'),('Richtige Werte lesen','Reifengröße und Beladungszustand auf dem Schild abgleichen. Normal-/Volllast- sowie Vorder-/Hinterachswerte nicht vertauschen.'),('Druck prüfen und korrigieren','Kalte Reifen unter den Herstellerbedingungen prüfen. Zuerst den tatsächlichen Druck messen und korrigieren; bloßes Löschen der Warnung ist nicht das Ziel.'),('System speichern oder einstellen','Infotainment-Speicherung, SET-Taste oder andere Verfahren nur dem passenden Modell und System zuordnen. Nach der Korrektur die Fahrzeuganleitung befolgen.')],
   [('Motoröle und SAE','SAE beschreibt die Viskositätsklasse, nicht allein die Herstellerfreigabe oder Motoreignung.'),('Volkswagen-Group-Freigaben','Die genaue Freigabe für Motor und Serviceregime verwenden. Gleiche Viskosität beweist keine Austauschbarkeit.'),('Auswahl, Füllstand und Nachfüllen','Konkreten Motor, Serviceregime und Anleitung beachten. Füllstand vorgeschrieben prüfen und nicht überfüllen.'),('Mischen und Notnachfüllen','Mischung oder Notnachfüllung muss für die Spezifikation ausdrücklich belegt sein; ein ähnlicher Produktname genügt nicht.'),('Getriebe- und weitere Öle','Schaltgetriebe, DSG, andere Automatikgetriebe, Verteilergetriebe, Differentiale und Allradkupplungen getrennt nach genauer Konstruktion beurteilen.')],
   [('Herstellerbezeichnung und Spezifikation','Farbe ist kein ausreichendes Auswahlkriterium. Maßgeblich ist die Spezifikation für Fahrzeug und Kühlkreis.'),('Konzentrat, Fertigmischung und Verdünnung','Konzentrat und Fertigmischung unterscheiden. Verdünnung, Wasseranforderung und Frostschutz aus der Anleitung übernehmen.'),('Mischbarkeit und Ersatz','Mischbarkeit oder Ersatz älterer Produkte nicht aus dem Handelsnamen ableiten. Herstellerbeleg für den Kreis ist erforderlich.'),('Sicher prüfen und nachfüllen','Heißen Kreis nie öffnen. Bei unbekannter Füllung, wiederholtem Verlust oder Warnung zuerst Ursache klären; Hybrid-/EV-Kreise unterscheiden.')],
   [('Passenden Wartungsplan wählen','Marke, Modell und Generation, Modelljahr, Motor/Antrieb, Getriebe sowie bei Bedarf VIN, Aggregat- und PR-Codes bestimmen.'),('Inspektion und Ölservice','Inspektion, Ölservice und Einzelarbeiten getrennt behandeln. Feste und flexible Regime haben unterschiedliche Bedingungen.'),('Filter, Kerzen, Steuer- und Nebenantriebe','Erste und folgende Termine sowie Zeit-/Kilometerbedingungen müssen aus dem passenden Wartungsplan stammen.'),('Getriebe, Allrad, Bremsen und Flüssigkeiten','Kein universelles DSG-, Automatik- oder 4×4-Intervall. Konstruktion, gewarteter Kreis, Öl und Filter entscheiden.'),('Ausstattungsspezifische Wartung','Prüfung, Ergänzung, regelmäßigen und zustandsabhängigen Wechsel unterscheiden. Herstellervorgabe und J&S-Prävention getrennt ausweisen.')]
  ]}
}

def main(lang,page):
 u=UI[lang];d=DRIVER_TOPICS[lang]
 intro={'cs':'Vyberte značku svého vozu a téma, které vás zajímá.','en':'Select your vehicle brand and the topic you are interested in.','de':'Wählen Sie Ihre Fahrzeugmarke und das gewünschte Thema.'}[lang]
 hierarchy={'cs':['Vozidlo a připojení','Bezpečnost a informace pro řidiče','Kapaliny a pohonné hmoty','Emise a údržba'],'en':['Vehicle and connectivity','Safety and driver information','Fluids and fuels','Emissions and maintenance'],'de':['Fahrzeug und Vernetzung','Sicherheit und Fahrerinformationen','Flüssigkeiten und Kraftstoffe','Abgas und Wartung']}[lang]
 topic_ids=['identifikace-vozu-vin','prihlaseni-online-sluzby','kontrolky','pojistky','tlak-pneumatik','oleje','chladici-kapaliny','servisni-intervaly','brzdova-kapalina','cisteni-vyfukovych-plynu','pohonne-hmoty','kapaliny-do-ostrikovacu']
 order=[0,1,2,3,4,10,5,6,8,11,9,7]
 group_at={0:hierarchy[0],2:hierarchy[1],5:hierarchy[2],10:hierarchy[3]}
 out=f'<main id="warning-lights" class="warning-lights driver-advice" lang="{lang}"><p class="driver-selection-intro">{esc(intro)}</p>{brand_selector_content(lang)}<section id="brand-advice" class="brand-advice" hidden aria-labelledby="brand-advice-title"><h2 id="brand-advice-title" tabindex="-1"></h2><div class="driver-topics" aria-label="{esc(d["page"])}">'
 for position,index in enumerate(order):
  title=d['titles'][index];topic_id=topic_ids[index]
  if position in group_at:out+=f'<h3 class="driver-topic-group-title">{esc(group_at[position])}</h3>'
  if index==0:topic_title=f'<span class="driver-topic-title"><span class="driver-vin-icon" aria-hidden="true">VIN</span>{esc(title)}</span>'
  elif index==1:topic_title=f'<span class="driver-topic-title"><span class="driver-profile-icon" aria-hidden="true"></span>{esc(title)}</span>'
  else:topic_title=f'<span>{esc(title)}</span>'
  out+=f'<details class="driver-topic" id="{topic_id}"><summary>{topic_title}<span class="driver-topic-arrow" aria-hidden="true"></span></summary><div class="driver-topic-body">'
  if index==0:out+=vin_content(lang)
  elif index==1:out+=online_services_content(lang)
  elif index==2:out+=warning_content(lang,page)
  else:
   if topic_id=='pojistky':
    out+=fuse_safety_content(lang)+'<div class="fuse-overview-layout"><div class="fuse-overview-copy">'
    for heading,text in d['topics'][index]:out+=f'<section class="driver-subtopic"><h2>{esc(heading)}</h2><p>{esc(text)}</p></section>'
    out+='</div>'+fuse_colour_content(lang)+'</div>'
   elif topic_id=='tlak-pneumatik':
    out+=tyre_content(lang)
    for heading,text in d['topics'][index]:out+=f'<section class="driver-subtopic"><h2>{esc(heading)}</h2><p>{esc(text)}</p></section>'
   elif topic_id=='chladici-kapaliny':out+=coolant_content(lang)
   elif topic_id=='oleje':out+=oil_content(lang)
   elif topic_id=='servisni-intervaly':out+=service_content(lang)
   elif topic_id=='brzdova-kapalina':out+=brake_fluid_content(lang)
   elif topic_id=='cisteni-vyfukovych-plynu':out+=emissions_content(lang)
   elif topic_id=='pohonne-hmoty':out+=fuels_content(lang)
